/* Contenido de «Inglés B2 (intermedio alto)». Archivo generado con herramientas/dividir-catalogo.js: no se edita a mano. */
window.MARA_CONTENIDO("c-ingles-b2",{"l":{"c-ingles-b2-m1-l1":[{"tipo":"destacado","texto":"<b>Antes de empezar:</b> este es un <b>curso libre de capacitación</b> con constancia de Instituto Mara. <b>No es una certificación de inglés</b> como Cambridge (B2 First), TOEFL o IELTS, ni tiene validez oficial ante la SEP. Si tu empresa o una beca te pide un nivel certificado, tendrás que presentar uno de esos exámenes por tu cuenta. Lo que sí hace este curso es trabajar las habilidades del nivel <b>B2 del Marco Común Europeo (MCER)</b>: el de un usuario que participa en juntas, defiende su postura, escribe textos profesionales claros y habla con cierta fluidez y naturalidad."},{"tipo":"texto","texto":"En las juntas de «lecciones aprendidas» (<i>lessons learned</i>, <i>post-mortem</i>) se habla mucho de lo que <b>habría pasado</b> si algo hubiera sido distinto. Para eso está el <b>third conditional</b>: <b>If + had + participio</b>, <b>would have + participio</b>. Habla de un pasado que <b>ya no se puede cambiar</b>: <i>If we <b>had checked</b> the parts, we <b>wouldn't have lost</b> the client.</i> = Si hubiéramos revisado las piezas, no habríamos perdido al cliente."},{"tipo":"tabla","titulo":"La estructura","voz":true,"colVoz":1,"encabezados":["Tipo","Ejemplo","Español"],"filas":[["Afirmativo","If I had known, I would have called you.","Si hubiera sabido, te habría llamado."],["Negativo","If the truck hadn't broken down, we would have delivered on time.","Si el camión no se hubiera descompuesto, habríamos entregado a tiempo."],["Con might / could","If you had asked, I could have helped.","Si me hubieras pedido, te habría podido ayudar."],["Orden invertido","We would have won the contract if our price had been lower.","Habríamos ganado el contrato si nuestro precio hubiera sido más bajo."],["Pregunta","What would you have done if you had been in my place?","¿Qué habrías hecho tú en mi lugar?"]],"nota":"<b>'d</b> puede ser <i>had</i> o <i>would</i>: <i>If I<b>'d</b> known, I<b>'d</b> have told you.</i> En la parte del <i>if</i> es <b>had</b>; junto a <i>have</i> es <b>would</b>."},{"tipo":"comparar","titulo":"El calco que más se oye","malTitulo":"Evita","mal":"<i>If I <b>would have</b> known, I would have told you.</i><br><i>If we <b>studied</b> more, we would have passed.</i>","bienTitulo":"Correcto","bien":"<i>If I <b>had known</b>, I would have told you.</i><br><i>If we <b>had studied</b> more, we would have passed.</i><br>El <i>would</i> nunca va en la parte del <i>if</i>."},{"tipo":"dialogo","titulo":"Diálogo — Post-mortem de un pedido retrasado en una planta de Ramos Arizpe","lineas":[{"quien":"Laura","en":"So, what went wrong with the Detroit order?","es":"Bueno, ¿qué salió mal con el pedido de Detroit?"},{"quien":"Iván","en":"The supplier sent the wrong resin. If we had inspected it on arrival, we would have caught the problem.","es":"El proveedor mandó la resina equivocada. Si la hubiéramos inspeccionado al llegar, habríamos detectado el problema."},{"quien":"Laura","en":"And why didn't we inspect it?","es":"¿Y por qué no la inspeccionamos?"},{"quien":"Iván","en":"Honestly, we were short-staffed. If we'd had one more technician, we could have done it.","es":"La verdad, nos faltaba personal. Si hubiéramos tenido un técnico más, lo habríamos podido hacer."},{"quien":"Laura","en":"OK. It's not about blaming anyone. What would you have done differently?","es":"Ok. No se trata de culpar a nadie. ¿Qué habrías hecho diferente?"},{"quien":"Iván","en":"I would have escalated it sooner. The delay wouldn't have been so long.","es":"Lo habría escalado antes. El retraso no habría sido tan largo."}]},{"tipo":"practica","rotulo":"Elige la forma correcta","preguntas":[{"p":"If she ___ the email, she would have replied.","ops":["had seen","would have seen","saw"],"correcta":0,"explica":"En la parte del <i>if</i> va <b>had + participio</b>."},{"p":"We ___ the flight if we had left earlier.","ops":["wouldn't miss","wouldn't have missed","hadn't missed"],"correcta":1},{"p":"«Si me hubieras avisado, te habría podido ayudar.»","ops":["If you told me, I could help you.","If you would have told me, I could have helped you.","If you had told me, I could have helped you."],"correcta":2},{"p":"En <i>If I'd known, I'd have come</i>, los dos <i>'d</i> son…","ops":["had y would","would y would","had y had"],"correcta":0},{"p":"¿Para qué sirve el third conditional?","ops":["Para planes reales en el futuro","Para imaginar un pasado distinto que ya no se puede cambiar","Para hablar de hábitos"],"correcta":1}]},{"tipo":"completar","rotulo":"Completa el análisis","voz":true,"items":[{"frase":"If we had ___ (test) the software, the system wouldn't have crashed.","resp":["tested"],"es":"Si hubiéramos probado el software, el sistema no se habría caído."},{"frase":"If the client ___ (not / cancel), we would have met our target.","resp":["hadn't cancelled","had not cancelled","hadn't canceled","had not canceled"],"es":"Si el cliente no hubiera cancelado, habríamos llegado a la meta."},{"frase":"I would ___ (take) the job if they had offered more money.","resp":["have taken"],"es":"Habría aceptado el trabajo si me hubieran ofrecido más dinero."},{"frase":"What would you have done if you ___ (be) the manager?","resp":["had been"],"es":"¿Qué habrías hecho si hubieras sido el gerente?"},{"frase":"She might have ___ (get) the promotion if she had applied.","resp":["got","gotten"],"es":"Quizá le habrían dado el ascenso si se hubiera postulado."}]},{"tipo":"pronunciar","rotulo":"Dilo con la forma reducida","frases":[{"en":"If I'd known, I would've called you.","pron":"if aid nóun ai údav cold iu","es":"Si hubiera sabido, te habría llamado."},{"en":"We wouldn't have lost the client.","pron":"ui údentav lost de cláient","es":"No habríamos perdido al cliente."},{"en":"What would you have done?","pron":"uát úyudav dan","es":"¿Qué habrías hecho tú?"},{"en":"If we'd checked the parts, we'd have caught it.","es":"Si hubiéramos revisado las piezas, lo habríamos detectado."}]},{"tipo":"clave","items":["Third conditional: <b>If + had + participio</b>, <b>would have + participio</b>.","Nunca pongas <i>would</i> en la parte del <i>if</i>: <i>If I had known</i>, no «If I would have known».","Al hablar, <i>would have</i> suena <i>would've</i> («údav»).","Curso libre con constancia de Instituto Mara; no sustituye Cambridge, TOEFL ni IELTS."]}],"c-ingles-b2-m1-l2":[{"tipo":"texto","texto":"La vida real no respeta los tiempos del libro. A veces una decisión <b>del pasado</b> explica tu <b>presente</b>: «Si no hubiera aceptado ese trabajo en Monterrey, <b>ahora</b> no hablaría inglés». Y a veces una característica <b>permanente</b> explica algo que <b>pasó</b>: «Si fuera más organizado, no habría olvidado la junta». Para eso se mezclan el second y el third conditional: son los <b>mixed conditionals</b>."},{"tipo":"tabla","titulo":"Las dos mezclas","voz":true,"colVoz":1,"encabezados":["Mezcla","Ejemplo","Español"],"filas":[["Pasado → presente","If I had taken that job, I would be living in Toronto now.","Si hubiera aceptado ese trabajo, ahora estaría viviendo en Toronto."],["Pasado → presente","If she hadn't studied English, she wouldn't be a team lead today.","Si no hubiera estudiado inglés, hoy no sería líder de equipo."],["Pasado → presente","If we had hired more people, we wouldn't be so stressed.","Si hubiéramos contratado más gente, no estaríamos tan estresados."],["Presente → pasado","If I were more organized, I wouldn't have missed the deadline.","Si fuera más organizado, no habría perdido la fecha límite."],["Presente → pasado","If he spoke English, they would have promoted him.","Si hablara inglés, lo habrían ascendido."]],"nota":"Pista: busca palabras como <i>now, today, still</i> (presente) o <i>yesterday, last year</i> (pasado) para saber qué mitad va en qué tiempo."},{"tipo":"dialogo","titulo":"Diálogo — Café después del turno en un call center de Mérida","lineas":[{"quien":"Sofía","en":"Do you ever think about what would have happened if you hadn't moved here?","es":"¿Alguna vez piensas qué habría pasado si no te hubieras mudado aquí?"},{"quien":"Diego","en":"All the time. If I hadn't moved to Mérida, I'd still be working at my uncle's shop.","es":"Todo el tiempo. Si no me hubiera mudado a Mérida, seguiría trabajando en la tienda de mi tío."},{"quien":"Sofía","en":"And you wouldn't be training new agents now.","es":"Y ahora no estarías capacitando a agentes nuevos."},{"quien":"Diego","en":"Exactly. What about you? You almost studied law, right?","es":"Exacto. ¿Y tú? Casi estudias Derecho, ¿no?"},{"quien":"Sofía","en":"Yes. If I were more patient, I would have finished the degree. But I love this job.","es":"Sí. Si fuera más paciente, habría terminado la carrera. Pero me encanta este trabajo."},{"quien":"Diego","en":"Well, if you had become a lawyer, we wouldn't know each other.","es":"Pues si te hubieras vuelto abogada, no nos conoceríamos."}]},{"tipo":"practica","rotulo":"¿Qué mezcla es?","preguntas":[{"p":"If I had saved more money, I ___ a car now.","ops":["would have","would have had","had"],"correcta":0,"explica":"Pasado (no ahorré) → presente (<i>now</i>): <b>would + verbo</b>."},{"p":"If she ___ so shy, she would have spoken at the meeting.","ops":["hadn't been","weren't","wouldn't be"],"correcta":1,"explica":"Es tímida siempre (presente) → no habló (pasado)."},{"p":"«Si hubiera dormido bien, no estaría tan cansado ahora.»","ops":["If I slept well, I wouldn't have been so tired.","If I had slept well, I wouldn't be so tired now.","If I would sleep well, I wouldn't be so tired now."],"correcta":1},{"p":"If he were a better planner, the project ___ late.","ops":["wouldn't be","won't be","wouldn't have been"],"correcta":2},{"p":"<i>If we had bought the house, we would be paying a mortgage now.</i> ¿Compraron la casa?","ops":["Sí","No","No se sabe"],"correcta":1}]},{"tipo":"relacionar","rotulo":"Une las dos mitades","voz":true,"pares":[["If I had accepted the offer in Canada,","I would be living in Vancouver now."],["If she were more confident,","she would have asked for a raise."],["If we had fixed the machine last week,","we wouldn't be behind schedule today."],["If I spoke German,","I would have got the job in Puebla."],["If they hadn't missed the flight,","they would be at the conference now."]]},{"tipo":"completar","rotulo":"Completa con la forma correcta","voz":true,"items":[{"frase":"If I had learned English as a kid, I ___ (be) more fluent now.","resp":["would be","'d be"],"es":"Si hubiera aprendido inglés de niño, ahora hablaría con más fluidez."},{"frase":"If he ___ (not / be) so stubborn, he would have listened to us.","resp":["weren't","wasn't","were not","was not"],"es":"Si no fuera tan terco, nos habría escuchado."},{"frase":"If we ___ (sign) the contract in May, we would be making money today.","resp":["had signed"],"es":"Si hubiéramos firmado el contrato en mayo, hoy estaríamos ganando dinero."},{"frase":"If I were you, I ___ (not / send) that email yesterday.","resp":["wouldn't have sent","would not have sent"],"es":"Yo en tu lugar no habría mandado ese correo ayer."}]},{"tipo":"pronunciar","rotulo":"Habla de tu trayectoria","frases":[{"en":"If I hadn't learned English, I wouldn't have this job.","pron":"if ai jádent lernd ínglish ai údent jav dis yob","es":"Si no hubiera aprendido inglés, no tendría este trabajo."},{"en":"If I were more patient, I would have finished it.","es":"Si fuera más paciente, lo habría terminado."},{"en":"I'd be living somewhere else now.","es":"Ahora estaría viviendo en otro lugar."}]},{"tipo":"reflexion","rotulo":"Tus decisiones","pregunta":"Escribe tres frases con mixed conditionals sobre tu vida: una decisión pasada y cómo cambió tu presente, algo que no hiciste y dónde estarías hoy, y un rasgo tuyo que explique algo que pasó.","ayuda":"If I hadn't…, I wouldn't be… now. / If I had…, I would be… / If I were more…, I would have…"},{"tipo":"clave","items":["Pasado → presente: <b>If + had + participio</b>, <b>would + verbo</b>.","Presente → pasado: <b>If + pasado</b>, <b>would have + participio</b>.","Las pistas de tiempo (<i>now, today, yesterday</i>) te dicen qué mitad cambia.","Ideales para hablar de tu trayectoria en una entrevista o una comida de trabajo."]}],"c-ingles-b2-m1-l3":[{"tipo":"texto","texto":"«Ojalá» se traduce de dos formas y es un error muy común mezclarlas. <b>hope</b> es para cosas <b>posibles</b>: <i>I hope you get the job</i> (ojalá te den el trabajo). <b>wish</b> es para cosas <b>imposibles o poco probables</b>, y obliga a «retroceder» un tiempo: si hablas del presente usas pasado; si hablas del pasado usas past perfect. <b>If only</b> es igual que <i>wish</i>, pero más dramático."},{"tipo":"tabla","titulo":"Tres usos de wish","voz":true,"colVoz":1,"encabezados":["Uso","Ejemplo","Español"],"filas":[["Presente (wish + pasado)","I wish I had more time.","Ojalá tuviera más tiempo."],["Presente con be","I wish I were in Cancún right now.","Ojalá estuviera en Cancún ahorita."],["Pasado (wish + past perfect)","I wish I had studied engineering.","Ojalá hubiera estudiado ingeniería."],["Arrepentimiento fuerte","If only I hadn't signed that contract!","¡Si tan solo no hubiera firmado ese contrato!"],["Molestia (wish + would)","I wish you would stop interrupting.","Ojalá dejaras de interrumpir."],["Algo posible (hope)","I hope the shipment arrives tomorrow.","Ojalá llegue el envío mañana."]],"nota":"<i>wish + would</i> se usa para quejarte de lo que <b>otra persona</b> hace. No se dice «I wish I would…»."},{"tipo":"comparar","titulo":"Hope contra wish","malTitulo":"Evita","mal":"<i>I wish you <b>have</b> a good trip.</i><br><i>I hope I <b>had</b> a bigger house.</i><br><i>I wish I <b>would</b> speak French.</i>","bienTitulo":"Correcto","bien":"<i>I <b>hope</b> you have a good trip.</i> (posible)<br><i>I <b>wish</b> I had a bigger house.</i> (no la tengo)<br><i>I <b>wish</b> I <b>spoke</b> French.</i>"},{"tipo":"escuchar","rotulo":"Escucha deseos y arrepentimientos","frases":[{"en":"I wish I had more time to study.","es":"Ojalá tuviera más tiempo para estudiar."},{"en":"I wish I hadn't said that in the meeting.","pron":"ai uísh ai jádent sed dat in de míting","es":"Ojalá no hubiera dicho eso en la junta."},{"en":"If only we had booked the hotel earlier!","es":"¡Si tan solo hubiéramos reservado el hotel antes!"},{"en":"I wish my neighbors would turn the music down.","es":"Ojalá mis vecinos le bajaran a la música."},{"en":"I hope you enjoy your stay in Oaxaca.","es":"Ojalá disfrutes tu estancia en Oaxaca."}]},{"tipo":"practica","rotulo":"¿Hope o wish? ¿Qué tiempo?","preguntas":[{"p":"I ___ it doesn't rain tomorrow. We have a tour in Tulum.","ops":["wish","want","hope","'d like"],"correcta":2,"explica":"Es algo posible → <b>hope</b> + presente. <i>Wish</i> es para lo irreal, y <i>want</i> o <i>'d like</i> no van seguidos de una oración así."},{"p":"I wish I ___ how to use this software. I have to ask every time.","ops":["knew","know","had known"],"correcta":0,"explica":"Deseo sobre el presente → pasado."},{"p":"I wish I ___ the job offer last year. It was a great company.","ops":["accepted","would accept","had accepted"],"correcta":2},{"p":"«Ojalá dejaras de llegar tarde» (me molesta):","ops":["I wish you stopped arriving late.","I wish you would stop arriving late.","I hope you stop arriving late."],"correcta":1,"explica":"Molestia por lo que hace otra persona → <b>wish + would</b>."},{"p":"«Ojalá estuviera de vacaciones» en inglés cuidado es…","ops":["I wish I were on vacation.","I wish I am on vacation.","I hope I was on vacation."],"correcta":0}]},{"tipo":"completar","rotulo":"Completa con la forma correcta","voz":true,"items":[{"frase":"I wish I ___ (can) speak to clients without notes.","resp":["could"],"es":"Ojalá pudiera hablar con los clientes sin notas."},{"frase":"If only I ___ (not / forget) my laptop at the hotel!","resp":["hadn't forgotten","had not forgotten"],"es":"¡Si tan solo no hubiera olvidado mi laptop en el hotel!"},{"frase":"I ___ you have a great time in Cancún.","resp":["hope"],"es":"Ojalá te la pases muy bien en Cancún."},{"frase":"I wish my boss ___ (give) clearer instructions.","resp":["would give","gave"],"es":"Ojalá mi jefe diera instrucciones más claras."},{"frase":"She wishes she ___ (live) closer to the plant.","resp":["lived"],"es":"Ella quisiera vivir más cerca de la planta."}]},{"tipo":"pronunciar","rotulo":"Dilo en voz alta","frases":[{"en":"I wish I had more time.","pron":"ai uísh ai jad mor táim","es":"Ojalá tuviera más tiempo."},{"en":"If only I'd known!","pron":"if óunli aid nóun","es":"¡Si tan solo lo hubiera sabido!"},{"en":"I wish you would listen to me.","es":"Ojalá me escucharas."}]},{"tipo":"clave","items":["<b>hope</b> = algo posible · <b>wish</b> = algo imposible o poco probable.","<i>wish</i> + pasado (presente) · <i>wish</i> + past perfect (pasado).","<i>wish + would</i> = molestia por lo que hace otra persona.","<i>If only…!</i> = <i>wish</i> con más emoción."]}],"c-ingles-b2-m1-l4":[{"tipo":"texto","texto":"En el trabajo no basta con decir <i>I like</i> o <i>I want</i>. Para <b>preferir con cortesía</b>, <b>advertir</b> o <b>decir que ya es hora</b> de hacer algo, el inglés tiene estructuras fijas que suenan muy naturales. El detalle: cada una exige una forma distinta del verbo, y ahí es donde se equivocan incluso los alumnos avanzados."},{"tipo":"tabla","titulo":"Las estructuras","voz":true,"colVoz":1,"encabezados":["Estructura","Ejemplo","Español"],"filas":[["would rather + verbo","I'd rather work from home on Fridays.","Prefiero trabajar desde casa los viernes."],["would rather + verbo + than","I'd rather call than write an email.","Prefiero llamar que escribir un correo."],["would rather + persona + pasado","I'd rather you didn't share this yet.","Preferiría que no compartieras esto todavía."],["prefer + -ing + to","I prefer working in teams to working alone.","Prefiero trabajar en equipo que solo."],["had better + verbo","We'd better leave now or we'll miss the flight.","Más vale que nos vayamos ya o perderemos el vuelo."],["it's time + persona + pasado","It's time we updated our prices.","Ya es hora de que actualicemos los precios."]],"nota":"<i>had better</i> no es pasado: es un consejo fuerte para <b>ahora</b>, casi una advertencia. Por eso casi siempre va contraído: <i>you'd better</i>."},{"tipo":"comparar","titulo":"Los errores más comunes","malTitulo":"Evita","mal":"<i>I would rather <b>to</b> stay.</i><br><i>You <b>had better to</b> call him.</i><br><i>I'd rather you <b>don't</b> tell anyone.</i><br><i>It's time we <b>update</b> the website.</i>","bienTitulo":"Correcto","bien":"<i>I'd rather <b>stay</b>.</i><br><i>You'd better <b>call</b> him.</i><br><i>I'd rather you <b>didn't</b> tell anyone.</i><br><i>It's time we <b>updated</b> the website.</i>"},{"tipo":"dialogo","titulo":"Diálogo — Planeando la visita de un cliente en Querétaro","lineas":[{"quien":"Paola","en":"The client arrives on Thursday. Would you rather take them to dinner downtown or at the hotel?","es":"El cliente llega el jueves. ¿Prefieres llevarlos a cenar al centro o en el hotel?"},{"quien":"Rodrigo","en":"I'd rather go downtown. They'd enjoy seeing the city.","es":"Prefiero el centro. Les gustaría conocer la ciudad."},{"quien":"Paola","en":"Good. But we'd better book a table today. It gets busy.","es":"Bien. Pero más vale que reservemos hoy. Se llena."},{"quien":"Rodrigo","en":"Agreed. And I'd rather you didn't mention the new prices at dinner.","es":"De acuerdo. Y preferiría que no mencionaras los precios nuevos en la cena."},{"quien":"Paola","en":"Don't worry. But honestly, it's time we told them. We can't wait forever.","es":"No te preocupes. Pero la verdad, ya es hora de que les digamos. No podemos esperar para siempre."}]},{"tipo":"practica","rotulo":"Elige la forma correcta","preguntas":[{"p":"I'd rather ___ by bus. It's cheaper.","ops":["to travel","travel","traveling"],"correcta":1},{"p":"You'd better ___ your passport. It expires next month.","ops":["renew","to renew","renewed"],"correcta":0},{"p":"I'd rather you ___ me before the meeting, not during it.","ops":["call","will call","called"],"correcta":2,"explica":"Con otra persona, <i>would rather</i> + <b>pasado</b>."},{"p":"It's high time the company ___ our salaries.","ops":["reviews","reviewed","review"],"correcta":1},{"p":"«Prefiero manejar que volar» con <i>prefer</i>:","ops":["I prefer driving to flying.","I prefer drive than fly.","I prefer to driving than flying."],"correcta":0}]},{"tipo":"ordenar","rotulo":"Arma la frase","voz":true,"items":[{"frase":"I'd rather not discuss it now","es":"Prefiero no hablarlo ahorita"},{"frase":"We'd better check the numbers again","es":"Más vale que revisemos los números otra vez"},{"frase":"It's time we hired a new supervisor","es":"Ya es hora de que contratemos a un supervisor nuevo"},{"frase":"I'd rather you didn't tell the client","es":"Preferiría que no le dijeras al cliente"}]},{"tipo":"pronunciar","rotulo":"Dilo con las contracciones","frases":[{"en":"I'd rather not.","pron":"aid ráder not","es":"Prefiero que no. / Mejor no."},{"en":"You'd better hurry.","pron":"iud béter jári","es":"Más vale que te apures."},{"en":"It's about time we changed suppliers.","es":"Ya va siendo hora de que cambiemos de proveedor."}]},{"tipo":"clave","items":["<b>would rather + verbo</b> (sin <i>to</i>) · con otra persona, + pasado.","<b>prefer + -ing + to + -ing</b> para gustos generales.","<b>had better + verbo</b> = más vale que… (consejo fuerte, presente).","<b>It's (high) time + persona + pasado</b> = ya es hora de que…"]}],"c-ingles-b2-m1-l5":[{"tipo":"texto","texto":"En el B1 aprendiste a deducir sobre el presente (<i>She must be in a meeting</i>). Ahora lo llevas al pasado con <b>modal + have + participio</b>. Sirve para dos cosas muy de trabajo: <b>juzgar</b> decisiones (<i>We should have told the client</i> = debimos avisarle al cliente) y <b>deducir</b> qué pasó a partir de las pistas (<i>The package must have got lost</i> = el paquete se debe haber perdido)."},{"tipo":"tabla","titulo":"Modales en pasado","voz":true,"colVoz":1,"encabezados":["Uso","Ejemplo","Español"],"filas":[["Crítica / arrepentimiento","We should have ordered more stock.","Debimos haber pedido más inventario."],["Crítica (negativa)","You shouldn't have signed without reading.","No debiste firmar sin leer."],["Oportunidad perdida","You could have asked me for help.","Me pudiste haber pedido ayuda."],["Deducción segura","He must have forgotten the meeting.","Se le debe haber olvidado la junta."],["Posibilidad","The email might have gone to spam.","A lo mejor el correo se fue a spam."],["Imposible","She can't have left already. Her car is here.","No puede haberse ido ya. Su coche está aquí."]],"nota":"Al hablar suenan reducidos: <i>should've</i> («shúdav»), <i>must've</i> («mástav»), <i>might've</i> («máitav»). Nunca se escribe «should of»."},{"tipo":"comparar","titulo":"Culpar contra hacerse responsable","malTitulo":"Suena a regaño","mal":"<i>You should have checked it! This is your fault.</i>","bienTitulo":"Suena profesional","bien":"<i><b>We</b> should have checked it earlier. <b>Next time</b>, let's add a second review.</i><br>Usar <i>we</i> y mirar hacia adelante baja la tensión."},{"tipo":"dialogo","titulo":"Diálogo — El proveedor no llegó a una obra en Guadalajara","lineas":[{"quien":"Mark","en":"The concrete truck was supposed to be here at seven. It's nine.","es":"El camión de concreto tenía que llegar a las siete. Son las nueve."},{"quien":"Carmen","en":"They might have gone to the old site. Their GPS still has that address.","es":"A lo mejor se fueron a la obra anterior. Su GPS todavía tiene esa dirección."},{"quien":"Mark","en":"They can't have gone there. I sent them the new address myself.","es":"No pueden haber ido ahí. Yo mismo les mandé la dirección nueva."},{"quien":"Carmen","en":"Then there must have been a problem at the plant. I'll call them.","es":"Entonces debió haber un problema en la planta. Les voy a llamar."},{"quien":"Mark","en":"We should have confirmed yesterday afternoon.","es":"Debimos haber confirmado ayer en la tarde."},{"quien":"Carmen","en":"You're right. From now on, we'll confirm every delivery the day before.","es":"Tienes razón. De ahora en adelante confirmaremos cada entrega un día antes."}]},{"tipo":"practica","rotulo":"Elige el modal correcto","preguntas":[{"p":"The lights are off and nobody answers. They ___ gone home.","ops":["must have","should have","can't have"],"correcta":0},{"p":"I failed the test. I ___ studied more.","ops":["must have","should have","might have"],"correcta":1},{"p":"She ___ written that report. She was on vacation all week.","ops":["must have","should have","can't have"],"correcta":2},{"p":"I'm not sure where my keys are. I ___ left them in the car.","ops":["might have","should have","can't have"],"correcta":0},{"p":"¿Cuál está bien escrita?","ops":["You should of called me.","You should have called me.","You should had called me."],"correcta":1,"explica":"Suena «should've», pero se escribe <b>should have</b>."}]},{"tipo":"completar","rotulo":"Completa con modal + have + participio","voz":true,"items":[{"frase":"You ___ told me about the change. I looked like a fool.","resp":["should have","should've","could have"],"es":"Me hubieras avisado del cambio. Quedé en ridículo."},{"frase":"The invoice must have ___ (get) lost in the mail.","resp":["got","gotten"],"es":"La factura se debe haber perdido en el correo."},{"frase":"He ___ have seen the message. His phone was off all day.","resp":["can't","couldn't"],"es":"No puede haber visto el mensaje. Tuvo el teléfono apagado todo el día."},{"frase":"We shouldn't have ___ (promise) such a short deadline.","resp":["promised"],"es":"No debimos prometer una fecha tan corta."},{"frase":"They might ___ taken a different route because of the traffic.","resp":["have"],"es":"A lo mejor tomaron otra ruta por el tráfico."}]},{"tipo":"pronunciar","rotulo":"Dilo con las formas reducidas","frases":[{"en":"We should've confirmed yesterday.","pron":"ui shúdav confírmd iésterdei","es":"Debimos haber confirmado ayer."},{"en":"He must've forgotten.","pron":"ji mástav forgóten","es":"Se le debe haber olvidado."},{"en":"It might've gone to spam.","pron":"it máitav gon tu spam","es":"A lo mejor se fue a spam."},{"en":"She can't have left already.","es":"No puede haberse ido ya."}]},{"tipo":"clave","items":["<b>should / shouldn't have</b> = crítica o arrepentimiento · <b>could have</b> = oportunidad perdida.","<b>must have</b> (seguro que sí) · <b>might have</b> (tal vez) · <b>can't have</b> (seguro que no).","Se dice «should've», pero se escribe <i>should have</i>.","Pasa a la evaluación del módulo: necesitas 80%."]}],"c-ingles-b2-m2-l1":[{"tipo":"texto","texto":"Un hablante B2 no dice todo en blanco y negro. <b>Hedging</b> es el arte de <b>suavizar</b>: presentar tus ideas como observaciones razonables y no como verdades absolutas. <i>The project is late</i> suena a acusación; <i>The project <b>seems to be</b> slightly behind schedule</i> dice lo mismo, pero abre la conversación. Ojo: suavizar no es esconder. El dato sigue ahí."},{"tipo":"tabla","titulo":"Herramientas para suavizar","voz":true,"colVoz":1,"encabezados":["Herramienta","Ejemplo","Español"],"filas":[["seem / appear","There seems to be a problem with the invoice.","Parece que hay un problema con la factura."],["tend to","Clients tend to prefer shorter contracts.","Los clientes suelen preferir contratos más cortos."],["might / could","This could be a good opportunity.","Esta podría ser una buena oportunidad."],["a bit / slightly / somewhat","The budget is slightly higher than expected.","El presupuesto es un poco más alto de lo esperado."],["it might be worth + -ing","It might be worth checking with legal first.","Quizá valga la pena consultarlo antes con jurídico."],["to some extent","I agree with that to some extent.","Estoy de acuerdo con eso hasta cierto punto."],["I'd say / I'd suggest","I'd say we need two more weeks.","Yo diría que necesitamos dos semanas más."],["as far as I know","As far as I know, the price hasn't changed.","Hasta donde sé, el precio no ha cambiado."]],"nota":"No los juntes todos en una frase: <i>It might possibly perhaps seem…</i> suena inseguro. Uno o dos por idea es suficiente."},{"tipo":"comparar","titulo":"Directo contra matizado","malTitulo":"Demasiado tajante","mal":"<i>Your forecast is wrong.</i><br><i>This supplier is bad.</i><br><i>We will lose money.</i>","bienTitulo":"Matizado y claro","bien":"<i>The forecast <b>seems</b> a bit optimistic.</i><br><i>This supplier <b>tends to</b> deliver late.</i><br><i>We <b>could</b> lose money if prices rise.</i>"},{"tipo":"escuchar","rotulo":"Escucha frases matizadas","frases":[{"en":"There seems to be a small mistake in the report.","pron":"der síms tu bi a smol mistéik in de ripórt","es":"Parece que hay un pequeño error en el informe."},{"en":"The new process appears to be working.","es":"El proceso nuevo parece estar funcionando."},{"en":"It might be worth talking to the team first.","es":"Quizá valga la pena hablar primero con el equipo."},{"en":"The results are somewhat disappointing.","pron":"de risálts ar sámuat disapóinting","es":"Los resultados son un tanto decepcionantes."},{"en":"As far as I know, nothing has been decided yet.","es":"Hasta donde sé, todavía no se ha decidido nada."}]},{"tipo":"practica","rotulo":"¿Cuál suena mejor en una junta?","preguntas":[{"p":"Quieres decir que el plan es caro.","ops":["The plan is too expensive. Forget it.","The plan seems a bit expensive for our budget.","This plan is stupid expensive."],"correcta":1},{"p":"Quieres sugerir que revisen el contrato.","ops":["It might be worth reviewing the contract.","Review the contract.","You must review the contract now."],"correcta":0},{"p":"No estás 100 % seguro de un dato.","ops":["The deadline is Friday. End of story.","The deadline is Friday, I think maybe possibly.","As far as I know, the deadline is Friday."],"correcta":2},{"p":"<i>Tend to</i> significa…","ops":["Tener que","Soler / tender a","Intentar"],"correcta":1},{"p":"¿Cuál es un exceso de hedging?","ops":["It seems a bit late.","It could perhaps possibly seem slightly late, maybe.","I'd say it's late."],"correcta":1}]},{"tipo":"completar","rotulo":"Suaviza la frase","voz":true,"items":[{"frase":"There ___ to be a problem with the server.","resp":["seems","appears"],"es":"Parece que hay un problema con el servidor."},{"frase":"Customers ___ to call more on Mondays.","resp":["tend"],"es":"Los clientes suelen llamar más los lunes."},{"frase":"The price is ___ higher than last year.","resp":["slightly","somewhat","a bit"],"es":"El precio es un poco más alto que el año pasado."},{"frase":"It might be ___ asking the supplier for a discount.","resp":["worth"],"es":"Quizá valga la pena pedirle un descuento al proveedor."},{"frase":"I agree with you to some ___.","resp":["extent"],"es":"Estoy de acuerdo contigo hasta cierto punto."}]},{"tipo":"pronunciar","rotulo":"Dilo con tono tranquilo","frases":[{"en":"It seems a bit optimistic.","pron":"it síms a bit optimístik","es":"Parece un poco optimista."},{"en":"I'd say we need more time.","es":"Yo diría que necesitamos más tiempo."},{"en":"To some extent, you're right.","pron":"tu sam ekstént iur ráit","es":"Hasta cierto punto, tienes razón."}]},{"tipo":"clave","items":["Hedging = suavizar la forma, no esconder el dato.","<i>seem, tend to, might, slightly, it might be worth…</i> son tus herramientas básicas.","Uno o dos suavizadores por idea; más suena inseguro.","Especialmente útil con culturas donde lo directo se siente agresivo."]}],"c-ingles-b2-m2-l2":[{"tipo":"texto","texto":"Los hablantes nativos rara vez dicen «no» a secas en el trabajo. Usan <b>trucos gramaticales</b> que bajan la temperatura: <b>1)</b> negar lo positivo en vez de afirmar lo negativo (<i>not ideal</i> en vez de <i>bad</i>); <b>2)</b> usar pasado o continuo para sonar menos directo (<i>I was wondering…</i>); <b>3)</b> usar pasiva para no señalar a nadie (<i>mistakes were made</i>); <b>4)</b> anunciar la mala noticia (<i>I'm afraid…, Unfortunately…</i>)."},{"tipo":"tabla","titulo":"Directo → diplomático","voz":true,"colVoz":1,"encabezados":["Directo","Diplomático","Español"],"filas":[["That's a bad idea.","I'm not sure that's the best approach.","No estoy seguro de que sea el mejor enfoque."],["The results are bad.","The results aren't quite what we expected.","Los resultados no son exactamente lo que esperábamos."],["No, we can't do that.","I'm afraid that won't be possible this month.","Me temo que eso no será posible este mes."],["I want a discount.","I was wondering if you could offer a discount.","Me preguntaba si nos podría ofrecer un descuento."],["You made a mistake.","It looks like there's been a mix-up with the order.","Parece que hubo una confusión con el pedido."],["You're late with the payment.","Our records show the payment hasn't been received yet.","Nuestros registros indican que aún no se ha recibido el pago."]]},{"tipo":"comparar","titulo":"Falsos amigos que causan malentendidos en juntas","malTitulo":"Evita","mal":"<i>I <b>pretend</b> to finish today.</i> (quieres decir «pretendo»)<br><i><b>Actually</b>, we have 200 clients.</i> (quieres decir «actualmente»)<br><i><b>Eventually</b> we will call you.</i> (quieres decir «de vez en cuando»)","bienTitulo":"Correcto","bien":"<i>I <b>intend</b> to finish today.</i> (<i>pretend</i> = fingir)<br><i><b>Currently</b>, we have 200 clients.</i> (<i>actually</i> = en realidad)<br><i>We may call you <b>from time to time</b>.</i> (<i>eventually</i> = al final, con el tiempo)"},{"tipo":"dialogo","titulo":"Diálogo — Decirle que no a un cliente en una agencia de Cancún","lineas":[{"quien":"Mr. Harris","en":"We'd like to move our group of forty people to the beach hotel next week.","es":"Queremos cambiar a nuestro grupo de cuarenta personas al hotel de playa la próxima semana."},{"quien":"Valeria","en":"I understand. Unfortunately, the beach hotel is fully booked that week, I'm afraid.","es":"Entiendo. Lamentablemente, me temo que el hotel de playa está lleno esa semana."},{"quien":"Mr. Harris","en":"That's not ideal. Isn't there anything you can do?","es":"Eso no es lo ideal. ¿No hay nada que pueda hacer?"},{"quien":"Valeria","en":"What I can do is offer you a hotel nearby with a private beach club, at the same price.","es":"Lo que sí puedo hacer es ofrecerle un hotel cercano con club de playa privado, al mismo precio."},{"quien":"Mr. Harris","en":"Hmm. I was hoping for something closer to the ruins, to be honest.","es":"Mmm. La verdad, esperaba algo más cerca de las ruinas."},{"quien":"Valeria","en":"I completely understand. Would it help if we included transportation to Tulum?","es":"Lo entiendo perfectamente. ¿Le ayudaría si incluimos el transporte a Tulum?"}]},{"tipo":"practica","rotulo":"Elige la versión diplomática","preguntas":[{"p":"Directo: <i>Your proposal is too expensive.</i>","ops":["Your proposal is very, very expensive.","Your proposal is a little bit bad.","Your proposal is a bit above our budget at the moment."],"correcta":2},{"p":"Directo: <i>I want to change the date.</i>","ops":["I was wondering if we could change the date.","Change the date, please.","I wanted that you change the date."],"correcta":0},{"p":"Directo: <i>You lost the documents.</i>","ops":["You always lose everything.","It seems the documents have been misplaced.","The documents, you lost them."],"correcta":1,"explica":"La pasiva quita el foco de la persona."},{"p":"<i>I pretend to finish today</i> significa en inglés…","ops":["Pretendo terminar hoy","Finjo terminar hoy","Espero terminar hoy"],"correcta":1},{"p":"¿Cuál es la forma más cortés de decir que no?","ops":["No.","That's impossible.","I'm afraid that won't be possible."],"correcta":2}]},{"tipo":"relacionar","rotulo":"Relaciona lo directo con lo diplomático","voz":true,"pares":[["That's not ideal.","Eso es un problema."],["I'm not sure I agree.","No estoy de acuerdo."],["I was wondering if you could help.","Ayúdame."],["That might be a little difficult.","No se puede."],["There's been a slight delay.","Vamos muy atrasados."]]},{"tipo":"pronunciar","rotulo":"Practica el tono diplomático","frases":[{"en":"I'm afraid that won't be possible.","pron":"aim afréid dat uóunt bi pósibol","es":"Me temo que eso no será posible."},{"en":"I was wondering if we could reschedule.","pron":"ai uas uándering if ui cud riskédiul","es":"Me preguntaba si podríamos reprogramar."},{"en":"The results aren't quite what we expected.","es":"Los resultados no son exactamente lo que esperábamos."},{"en":"What I can do is offer you an alternative.","es":"Lo que sí puedo hacer es ofrecerle una alternativa."}]},{"tipo":"clave","items":["Niega lo positivo: <i>not ideal, not quite, not the best</i>.","<i>I was wondering if…</i> suena más cortés que <i>I want</i>.","La pasiva (<i>there's been a mix-up</i>) evita culpar.","Después de un «no», ofrece algo: <i>What I can do is…</i>"]}],"c-ingles-b2-m2-l3":[{"tipo":"texto","texto":"Persuadir en inglés no es hablar más fuerte. Es seguir una lógica que tu audiencia reconoce: <b>1)</b> mostrar que entiendes el problema, <b>2)</b> presentar tu propuesta, <b>3)</b> hablar de <b>beneficios para ellos</b> (no para ti), <b>4)</b> adelantarte a las objeciones y <b>5)</b> pedir una decisión concreta. Las preguntas negativas (<i>Wouldn't it be better…?</i>) invitan a la otra persona a estar de acuerdo."},{"tipo":"tabla","titulo":"Frases para persuadir","voz":true,"colVoz":1,"encabezados":["Paso","Frase","Español"],"filas":[["Reconocer el problema","We all know that turnover has been a real issue.","Todos sabemos que la rotación ha sido un problema serio."],["Proponer","What I'm proposing is a pilot program for three months.","Lo que propongo es un programa piloto de tres meses."],["Beneficio","This would allow us to cut training costs.","Esto nos permitiría reducir costos de capacitación."],["Pregunta retórica","Wouldn't it make sense to try it first?","¿No tendría sentido probarlo primero?"],["Anticipar objeción","I know what you're thinking: it sounds expensive. But…","Sé lo que están pensando: suena caro. Pero…"],["Datos","The numbers speak for themselves.","Los números hablan por sí solos."],["Pedir decisión","All I'm asking for is a green light for the pilot.","Lo único que pido es luz verde para el piloto."]]},{"tipo":"dialogo","titulo":"Diálogo — Proponer home office en una empresa de software en Guadalajara","lineas":[{"quien":"Andrea","en":"We all know we've lost five developers this year. That's a real problem.","es":"Todos sabemos que este año perdimos a cinco desarrolladores. Es un problema serio."},{"quien":"Andrea","en":"What I'm proposing is two remote days a week, starting with one team.","es":"Lo que propongo son dos días remotos a la semana, empezando con un equipo."},{"quien":"Mr. Collins","en":"I'm worried productivity will drop.","es":"Me preocupa que baje la productividad."},{"quien":"Andrea","en":"I understand that concern. But companies that tried it saw productivity stay the same or go up.","es":"Entiendo esa preocupación. Pero las empresas que lo probaron vieron que la productividad se mantuvo o subió."},{"quien":"Andrea","en":"And replacing one developer costs us about three months of salary. Wouldn't it make sense to try?","es":"Y reemplazar a un desarrollador nos cuesta unos tres meses de sueldo. ¿No tendría sentido intentarlo?"},{"quien":"Mr. Collins","en":"Fair enough. Let's run a three-month pilot and review the numbers.","es":"Me parece justo. Hagamos un piloto de tres meses y revisemos los números."}]},{"tipo":"practica","rotulo":"¿Entendiste la estrategia?","preguntas":[{"p":"¿Cómo empieza Andrea su argumento?","ops":["Con su propuesta","Reconociendo un problema que todos conocen","Con una queja personal"],"correcta":1},{"p":"¿Qué objeción pone Mr. Collins?","ops":["Que baje la productividad","Que cueste mucho","Que el equipo no quiera"],"correcta":0},{"p":"¿Cómo responde Andrea a la objeción?","ops":["Se enoja","Cambia de tema","Reconoce la preocupación y da datos"],"correcta":2},{"p":"<i>Wouldn't it make sense to try?</i> busca…","ops":["Que el otro diga que no","Que el otro reconozca que sí","Cerrar la junta"],"correcta":1},{"p":"<i>Fair enough</i> significa…","ops":["Me parece justo / Está bien","Es suficiente, cállate","No es justo"],"correcta":0}]},{"tipo":"ordenar","rotulo":"Arma frases persuasivas","voz":true,"items":[{"frase":"Wouldn't it make sense to start with a pilot?","es":"¿No tendría sentido empezar con un piloto?"},{"frase":"This would allow us to reduce costs","es":"Esto nos permitiría reducir costos"},{"frase":"All I'm asking for is one month","es":"Lo único que pido es un mes"},{"frase":"The numbers speak for themselves","es":"Los números hablan por sí solos"}]},{"tipo":"pronunciar","rotulo":"Convence en voz alta","frases":[{"en":"What I'm proposing is a three-month pilot.","pron":"uát aim propóusing is a zri manz páilot","es":"Lo que propongo es un piloto de tres meses."},{"en":"Wouldn't it make sense to try it first?","pron":"údent it méik sens tu trái it ferst","es":"¿No tendría sentido probarlo primero?"},{"en":"I understand that concern, but the data shows otherwise.","es":"Entiendo esa preocupación, pero los datos muestran otra cosa."}]},{"tipo":"reflexion","rotulo":"Tu propuesta","pregunta":"Piensa en algo que te gustaría cambiar en tu trabajo o tu comunidad. Escribe un argumento de 5 frases siguiendo los pasos: problema, propuesta, beneficio, objeción anticipada y petición concreta. Dilo en voz alta en menos de un minuto.","ayuda":"We all know that… / What I'm proposing is… / This would allow us to… / I know what you're thinking, but… / All I'm asking for is…"},{"tipo":"clave","items":["Problema → propuesta → beneficio → objeción → petición.","Habla de beneficios para <b>ellos</b> y apóyate en datos.","Las preguntas negativas (<i>Wouldn't it…?</i>) invitan al «sí».","Termina pidiendo algo concreto y pequeño: un piloto, una prueba, una fecha."]}],"c-ingles-b2-m2-l4":[{"tipo":"texto","texto":"En una junta con nativos que hablan rápido, el reto no es entender: es <b>encontrar el momento</b> de hablar y <b>no soltar el turno</b> cuando te interrumpen. En el B1 aprendiste <i>Sorry to interrupt</i>. Aquí van frases más finas: entrar sin brusquedad, sostener tu punto con amabilidad, «estacionar» un tema que desvía la junta y dar la palabra a otros, que es lo que hace un buen líder."},{"tipo":"tabla","titulo":"Control del turno","voz":true,"colVoz":1,"encabezados":["Situación","Frase","Español"],"filas":[["Entrar con suavidad","If I could just come in here…","Si me permiten intervenir aquí…"],["Entrar con suavidad","Can I just pick up on what Ana said?","¿Puedo retomar lo que dijo Ana?"],["Mantener el turno","Sorry, can I just finish my point?","Perdón, ¿puedo terminar mi idea?"],["Mantener el turno","Bear with me for one second.","Denme un segundo."],["Estacionar un tema","Good point. Let's park that for now.","Buen punto. Dejémoslo pendiente por ahora."],["Estacionar un tema","Can we take that offline?","¿Lo vemos aparte, fuera de la junta?"],["Regresar al tema","Going back to the budget…","Regresando al presupuesto…"],["Ceder la palabra","Luis, we haven't heard from you yet.","Luis, todavía no te hemos escuchado."]],"nota":"<i>Take it offline</i> no tiene que ver con internet: significa hablarlo después, en privado o con menos personas."},{"tipo":"escuchar","rotulo":"Escucha fragmentos de una junta","frases":[{"en":"If I could just come in here for a second…","pron":"if ai cud yast cam in jíer","es":"Si me permiten intervenir aquí un segundo…"},{"en":"Sorry, can I just finish my point?","es":"Perdón, ¿puedo terminar mi idea?"},{"en":"That's a good point, but let's park it for now.","es":"Es buen punto, pero dejémoslo pendiente por ahora."},{"en":"I think we're getting a bit off track.","es":"Creo que nos estamos desviando un poco."},{"en":"Carla, what's your take on this?","es":"Carla, ¿tú qué opinas de esto?"}]},{"tipo":"dialogo","titulo":"Diálogo — Junta de planeación con la matriz en Chicago","lineas":[{"quien":"Greg","en":"So we move the launch to March, we cut the marketing budget, and we—","es":"Entonces movemos el lanzamiento a marzo, recortamos el presupuesto de marketing y—"},{"quien":"Mónica","en":"Sorry, Greg, if I could just come in here. Cutting marketing in March is risky.","es":"Perdón, Greg, si me permites intervenir. Recortar marketing en marzo es arriesgado."},{"quien":"Greg","en":"But the numbers—","es":"Pero los números—"},{"quien":"Mónica","en":"Bear with me, I'll be quick. March is our busiest month in Mexico.","es":"Dame un segundo, seré breve. Marzo es nuestro mes más fuerte en México."},{"quien":"Greg","en":"OK, fair point. But now we're getting into pricing. Can we take that offline?","es":"Ok, buen punto. Pero ya nos estamos metiendo en precios. ¿Lo vemos aparte?"},{"quien":"Mónica","en":"Sure. Going back to the launch date, Raúl, what's your take?","es":"Claro. Regresando a la fecha de lanzamiento, Raúl, ¿tú qué opinas?"}]},{"tipo":"practica","rotulo":"¿Qué frase usas?","preguntas":[{"p":"Alguien te interrumpe a media explicación.","ops":["Shut up, please.","Sorry, can I just finish my point?","Stop talking."],"correcta":1},{"p":"La junta se desvió hacia un tema que no toca hoy.","ops":["Let's park that for now.","That is not important.","Change the topic."],"correcta":0},{"p":"Quieres escuchar a alguien que no ha hablado.","ops":["You, talk.","Why are you so quiet?","We haven't heard from you yet, Sara."],"correcta":2},{"p":"<i>Can we take that offline?</i> significa…","ops":["¿Podemos desconectarnos?","¿Lo hablamos aparte después?","¿Apagamos la cámara?"],"correcta":1},{"p":"<i>What's your take on this?</i> significa…","ops":["¿Qué te llevas?","¿Cuánto cuesta?","¿Qué opinas de esto?"],"correcta":2}]},{"tipo":"completar","rotulo":"Completa las frases de control","voz":true,"items":[{"frase":"If I could just ___ in here, I have a quick comment.","resp":["come"],"es":"Si me permiten intervenir, tengo un comentario rápido."},{"frase":"Sorry, can I just ___ my point?","resp":["finish"],"es":"Perdón, ¿puedo terminar mi idea?"},{"frase":"I think we're getting a bit off ___.","resp":["track","topic"],"es":"Creo que nos estamos desviando un poco."},{"frase":"___ back to the schedule, when is the deadline?","resp":["Going","Getting"],"es":"Regresando al calendario, ¿cuál es la fecha límite?"}]},{"tipo":"pronunciar","rotulo":"Dilo con seguridad","frases":[{"en":"Bear with me for one second.","pron":"ber uíz mi for uan sékond","es":"Denme un segundo."},{"en":"Let's park that for now.","es":"Dejémoslo pendiente por ahora."},{"en":"Can we take that offline?","pron":"can ui téik dat ofláin","es":"¿Lo vemos aparte?"}]},{"tipo":"clave","items":["Entra con <i>If I could just come in here…</i>","Defiende tu turno: <i>Can I just finish my point?</i> / <i>Bear with me.</i>","Redirige: <i>Let's park that / take it offline / Going back to…</i>","Dar la palabra a otros también es liderazgo: <i>What's your take?</i>"]}],"c-ingles-b2-m2-l5":[{"tipo":"texto","texto":"En el B1 negociaste planes sencillos con <i>What if we…?</i> y <i>as long as</i>. Una negociación profesional tiene más capas: <b>explorar</b> lo que necesita la otra parte, <b>ofrecer concesiones con condición</b> (nunca regalar nada), marcar tus <b>límites</b> y, al final, <b>resumir</b> los acuerdos para que no haya malentendidos. La regla de oro: <i>If you give something, get something.</i>"},{"tipo":"tabla","titulo":"Lenguaje de negociación","voz":true,"colVoz":1,"encabezados":["Etapa","Frase","Español"],"filas":[["Explorar","What's most important to you in this deal?","¿Qué es lo más importante para ustedes en este trato?"],["Concesión con condición","We could lower the price, provided that you sign for two years.","Podríamos bajar el precio, siempre y cuando firmen por dos años."],["Concesión con condición","On condition that you pay in advance, we can offer 5% off.","Con la condición de que paguen por adelantado, podemos dar 5 % de descuento."],["Contraoferta","What we could do is split the shipping costs.","Lo que podríamos hacer es dividir los costos de envío."],["Punto medio","Let's meet halfway.","Encontremos un punto medio."],["Límite","I'm afraid that's a deal-breaker for us.","Me temo que eso es inaceptable para nosotros."],["Ganar tiempo","I'll need to run this by my director.","Tendré que consultarlo con mi director."],["Cerrar","Let me recap what we've agreed.","Déjame resumir lo que acordamos."]],"nota":"<i>provided that</i> y <i>on condition that</i> van con <b>presente</b>, aunque hablen del futuro, igual que <i>if</i>."},{"tipo":"dialogo","titulo":"Diálogo — Un distribuidor de Texas y una fábrica de muebles en Jalisco","lineas":[{"quien":"Mr. Scott","en":"Your price is about 10% above what we can pay.","es":"Su precio está como 10 % arriba de lo que podemos pagar."},{"quien":"Gabriela","en":"I see. What's most important to you: price or delivery time?","es":"Ya veo. ¿Qué es más importante para ustedes: precio o tiempo de entrega?"},{"quien":"Mr. Scott","en":"Price, definitely. We can be flexible on delivery.","es":"El precio, sin duda. Podemos ser flexibles con la entrega."},{"quien":"Gabriela","en":"In that case, we could lower the price by 6%, provided that you accept delivery in eight weeks instead of four.","es":"En ese caso, podríamos bajar el precio 6 %, siempre y cuando acepten la entrega en ocho semanas en vez de cuatro."},{"quien":"Mr. Scott","en":"Eight weeks is too long, I'm afraid. Could we meet halfway, at six?","es":"Me temo que ocho semanas es mucho. ¿Podemos encontrar un punto medio, en seis?"},{"quien":"Gabriela","en":"Six weeks and 5% off. I'll need to run it by my director, but I think we have a deal.","es":"Seis semanas y 5 % de descuento. Tengo que consultarlo con mi director, pero creo que tenemos un trato."},{"quien":"Mr. Scott","en":"Great. Can you send me an email recapping what we've agreed?","es":"Excelente. ¿Me puedes mandar un correo resumiendo lo que acordamos?"}]},{"tipo":"practica","rotulo":"¿Entendiste la negociación?","preguntas":[{"p":"¿Qué le importa más a Mr. Scott?","ops":["El tiempo de entrega","El precio","La calidad"],"correcta":1},{"p":"¿Qué pide Gabriela a cambio del descuento?","ops":["Más tiempo de entrega","Pago por adelantado","Un contrato de dos años"],"correcta":0},{"p":"¿En qué quedan?","ops":["8 semanas y 6 % de descuento","4 semanas y sin descuento","6 semanas y 5 % de descuento"],"correcta":2},{"p":"<i>I'll need to run it by my director</i> significa…","ops":["Tengo que correr con mi director","Tengo que consultarlo con mi director","Mi director va a manejar esto"],"correcta":1},{"p":"Completa: <i>We can offer free shipping provided that you ___ 500 units.</i>","ops":["order","will order","would order"],"correcta":0,"explica":"Después de <i>provided that</i>, presente."}]},{"tipo":"completar","rotulo":"Completa la negociación","voz":true,"items":[{"frase":"We could extend the warranty, ___ that you sign today.","resp":["provided","providing"],"es":"Podríamos extender la garantía, siempre y cuando firmen hoy."},{"frase":"What we ___ do is split the cost fifty-fifty.","resp":["could","can"],"es":"Lo que podríamos hacer es dividir el costo a la mitad."},{"frase":"Let's meet ___ on the delivery date.","resp":["halfway"],"es":"Encontremos un punto medio en la fecha de entrega."},{"frase":"Exclusivity is a deal-___ for us, I'm afraid.","resp":["breaker"],"es":"Me temo que la exclusividad es inaceptable para nosotros."},{"frase":"Let me ___ what we've agreed so far.","resp":["recap","summarize","summarise"],"es":"Déjame resumir lo que hemos acordado hasta ahora."}]},{"tipo":"pronunciar","rotulo":"Negocia en voz alta","frases":[{"en":"Provided that you pay in advance, we can offer a discount.","pron":"prováided dat iu péi in adváns","es":"Siempre y cuando paguen por adelantado, podemos ofrecer un descuento."},{"en":"Let's meet halfway.","pron":"lets mit jáfuei","es":"Encontremos un punto medio."},{"en":"I'm afraid that's a deal-breaker for us.","es":"Me temo que eso es inaceptable para nosotros."},{"en":"Let me recap what we've agreed.","es":"Déjame resumir lo que acordamos."}]},{"tipo":"clave","items":["Explora antes de ofrecer: <i>What's most important to you?</i>","Nunca regales: concede <b>con condición</b> (<i>provided that, on condition that</i>).","Marca límites con cortesía: <i>I'm afraid that's a deal-breaker.</i>","Cierra resumiendo por escrito lo acordado. Pasa a la evaluación: necesitas 80%."]}],"c-ingles-b2-m3-l1":[{"tipo":"texto","texto":"Cuando lees un documento puedes regresar la página; cuando escuchas una presentación, no. Por eso los buenos presentadores usan <b>signposting</b>: frases que funcionan como letreros en la carretera. Dicen <b>a dónde vamos</b> (<i>I'll cover three points</i>), <b>cuándo cambiamos de tema</b> (<i>Let's move on to…</i>) y <b>dónde estamos</b> (<i>So far we've looked at…</i>). En inglés se usan mucho más que en español; si no las pones, tu presentación suena desordenada aunque el contenido sea bueno."},{"tipo":"tabla","titulo":"Letreros para cada momento","voz":true,"colVoz":1,"encabezados":["Momento","Frase","Español"],"filas":[["Abrir","Thanks for having me. Today I'd like to walk you through our results.","Gracias por recibirme. Hoy quiero explicarles paso a paso nuestros resultados."],["Dar el mapa","I've divided my talk into three parts.","Dividí mi presentación en tres partes."],["Primer punto","Let's start with the background.","Empecemos con los antecedentes."],["Cambiar de tema","That brings me to my second point.","Eso me lleva a mi segundo punto."],["Cambiar de tema","Let's move on to the budget.","Pasemos al presupuesto."],["Desviarse un momento","Just to digress for a moment…","Me desvío un momento…"],["Ubicar a la audiencia","So far, we've looked at the problem. Now let's look at the solution.","Hasta ahora vimos el problema. Ahora veamos la solución."],["Cerrar","To sum up, there are three key takeaways.","Para resumir, hay tres ideas clave."],["Abrir preguntas","I'd be happy to take any questions.","Con gusto respondo sus preguntas."]],"nota":"<i>Walk someone through something</i> = explicar algo paso a paso. Es de las frases más usadas en presentaciones de negocios."},{"tipo":"comparar","titulo":"Calcos del español que se oyen mucho","malTitulo":"Evita","mal":"<i>I'm going to <b>present you</b> the results.</i><br><i>Let me <b>explain you</b> the process.</i><br><i><b>In resume</b>, sales went up.</i><br><i>Now I will <b>pass to</b> the next point.</i>","bienTitulo":"Correcto","bien":"<i>I'm going to <b>present the results to you</b>.</i><br><i>Let me <b>explain the process to you</b>.</i><br><i><b>To sum up / In short</b>, sales went up.</i><br><i>Now let's <b>move on to</b> the next point.</i>"},{"tipo":"practica","rotulo":"¿Qué letrero usas?","preguntas":[{"p":"Terminaste de hablar del problema y vas a hablar de la solución.","ops":["That brings me to the solution.","In resume, the solution.","Now I pass to the solution."],"correcta":0},{"p":"Quieres decir al principio cuántas partes tiene tu presentación.","ops":["I will talk and talk.","I've divided my talk into three parts.","My talk has many points, maybe."],"correcta":1},{"p":"<i>Let me walk you through the process</i> significa…","ops":["Déjame caminar contigo","Déjame explicarte el proceso paso a paso","Déjame saltarme el proceso"],"correcta":1},{"p":"«Déjame explicarte el plan» se dice…","ops":["Let me explain you the plan.","Let me explain to you the plan please.","Let me explain the plan to you."],"correcta":2,"explica":"<i>explain</i> no lleva a la persona inmediatamente después: <i>explain <b>something to</b> someone</i>."},{"p":"¿Cuál es un buen cierre?","ops":["To sum up, there are three key takeaways.","In resume, that's all.","Finish. Questions?"],"correcta":0}]},{"tipo":"ordenar","rotulo":"Arma los letreros","voz":true,"items":[{"frase":"Today I'd like to walk you through our results","es":"Hoy quiero explicarles paso a paso nuestros resultados"},{"frase":"That brings me to my second point","es":"Eso me lleva a mi segundo punto"},{"frase":"So far we've looked at the costs","es":"Hasta ahora hemos visto los costos"},{"frase":"I'd be happy to take any questions","es":"Con gusto respondo sus preguntas"}]},{"tipo":"pronunciar","rotulo":"Abre tu presentación en voz alta","frases":[{"en":"Thanks for having me.","pron":"zanks for jáving mi","es":"Gracias por recibirme."},{"en":"I'd like to walk you through our results.","pron":"aid láik tu uok iu zru áuer risálts","es":"Quiero explicarles paso a paso nuestros resultados."},{"en":"Let's move on to the budget.","pron":"lets muv on tu de báyet","es":"Pasemos al presupuesto."},{"en":"To sum up, there are three key takeaways.","pron":"tu sam ap der ar zri ki téikaueis","es":"Para resumir, hay tres ideas clave."}]},{"tipo":"clave","items":["Signposting = letreros que dicen a dónde vas, dónde estás y cuándo cambias de tema.","<i>walk you through, move on to, that brings me to, so far, to sum up</i>.","<i>explain / present <b>something to</b> someone</i>, nunca «explain you».","En inglés se «señaliza» más que en español: no te dé pena repetir la estructura."]}],"c-ingles-b2-m3-l2":[{"tipo":"texto","texto":"Las mejores presentaciones cuentan una historia: <i>había un problema, hicimos algo, logramos esto</i>. Para contarla bien necesitas <b>cuatro tiempos narrativos</b>. El <b>pasado simple</b> hace avanzar la historia. El <b>pasado continuo</b> pinta el escenario. El <b>past perfect</b> (<i>had + participio</i>) mira hacia atrás: lo que ya había pasado. Y el <b>past perfect continuous</b> (<i>had been + -ing</i>) dice cuánto tiempo <b>llevaba</b> pasando algo antes de ese momento."},{"tipo":"tabla","titulo":"Los cuatro tiempos narrativos","voz":true,"colVoz":1,"encabezados":["Tiempo","Ejemplo","Para qué"],"filas":[["Pasado simple","We launched the app in May.","Los hechos principales, en orden"],["Pasado continuo","The team was working day and night.","El escenario, lo que estaba en curso"],["Past perfect","By then, we had lost two big clients.","Algo que ya había pasado antes"],["Past perfect continuous","We had been losing money for months.","Cuánto tiempo llevaba pasando algo"],["Combinados","When I joined, the plant had been running at a loss for a year.","Cuando entré, la planta llevaba un año operando con pérdidas."]],"nota":"<b>by then, by the time, already, for, since</b> son pistas del past perfect. Si el orden ya está claro con <i>after</i> o <i>before</i>, el pasado simple también se acepta."},{"tipo":"dialogo","titulo":"Diálogo — Un caso de éxito ante la matriz: un hotel boutique en Oaxaca","lineas":[{"quien":"Elena","en":"When I took over the hotel in 2022, it had been losing guests for three years.","es":"Cuando me hice cargo del hotel en 2022, llevaba tres años perdiendo huéspedes."},{"quien":"Elena","en":"The online reviews were terrible. Guests had been complaining about slow check-ins and noise.","es":"Las reseñas en línea eran terribles. Los huéspedes llevaban tiempo quejándose del check-in lento y del ruido."},{"quien":"Mr. Reed","en":"What did you do first?","es":"¿Qué hiciste primero?"},{"quien":"Elena","en":"I listened. While the staff were telling me their ideas, I realized nobody had asked them before.","es":"Escuché. Mientras el personal me contaba sus ideas, me di cuenta de que nadie les había preguntado antes."},{"quien":"Elena","en":"So we fixed the windows, trained the front desk and started offering mezcal tastings.","es":"Así que arreglamos las ventanas, capacitamos a recepción y empezamos a ofrecer catas de mezcal."},{"quien":"Elena","en":"By the end of the year, our rating had gone up from 3.2 to 4.6.","es":"Para fin de año, nuestra calificación había subido de 3.2 a 4.6."}]},{"tipo":"practica","rotulo":"¿Qué tiempo va?","preguntas":[{"p":"When I arrived at the meeting, it ___. I had to wait for the next break.","ops":["already started","had already started","has already started"],"correcta":1,"explica":"La junta empezó <b>antes</b> de que yo llegara → past perfect."},{"p":"They ___ for the supplier for two hours when he finally called.","ops":["had been waiting","were waiting","waited"],"correcta":0,"explica":"Cuánto tiempo llevaban → <b>had been + -ing</b>."},{"p":"While we ___ the new line, the power went out.","ops":["had installed","were installing","installed"],"correcta":1},{"p":"«Cuando entré, la empresa llevaba dos años sin crecer.»","ops":["When I joined, the company didn't grow for two years.","When I joined, the company hasn't grown for two years.","When I joined, the company hadn't grown for two years."],"correcta":2},{"p":"En el diálogo, ¿qué había pasado antes de que llegara Elena?","ops":["El hotel llevaba tres años perdiendo huéspedes","El hotel había subido su calificación","Nadie se quejaba"],"correcta":0}]},{"tipo":"completar","rotulo":"Completa la historia","voz":true,"items":[{"frase":"By the time the auditor arrived, we ___ (fix) all the issues.","resp":["had fixed","had already fixed"],"es":"Para cuando llegó el auditor, ya habíamos corregido todos los problemas."},{"frase":"The machine had ___ (make) a strange noise for days before it stopped.","resp":["been making"],"es":"La máquina llevaba días haciendo un ruido raro antes de detenerse."},{"frase":"I ___ (drive) to the airport when the client called.","resp":["was driving"],"es":"Iba manejando al aeropuerto cuando llamó el cliente."},{"frase":"We ___ (sign) the contract the next morning.","resp":["signed"],"es":"Firmamos el contrato a la mañana siguiente."},{"frase":"She was exhausted because she ___ (work) since 6 a.m.","resp":["had been working"],"es":"Estaba agotada porque llevaba trabajando desde las 6 de la mañana."}]},{"tipo":"pronunciar","rotulo":"Cuenta la historia en voz alta","frases":[{"en":"It had been losing guests for three years.","pron":"it jad bin lúsing gests for zri yírs","es":"Llevaba tres años perdiendo huéspedes."},{"en":"By then, we'd already lost two clients.","pron":"bai den uid olrédi lost tu cláients","es":"Para entonces ya habíamos perdido a dos clientes."},{"en":"While we were fixing it, the client called.","es":"Mientras lo estábamos arreglando, llamó el cliente."}]},{"tipo":"clave","items":["Pasado simple = hechos · pasado continuo = escenario.","Past perfect (<i>had done</i>) = lo que ya había pasado antes.","Past perfect continuous (<i>had been doing</i>) = cuánto tiempo llevaba pasando.","Estructura tu caso: situación difícil → lo que hiciste → resultado con datos."]}],"c-ingles-b2-m3-l3":[{"tipo":"texto","texto":"Los <b>discourse markers</b> son las palabras que «pegan» tus ideas y le avisan al oyente qué viene: una idea extra, un contraste, una aclaración o una conclusión. Sin ellos hablas en frases sueltas; con ellos suenas organizado y seguro. Muchos son distintos al hablar y al escribir: <i>on top of that</i> es muy oral, mientras que <i>furthermore</i> es más de texto."},{"tipo":"tabla","titulo":"Marcadores por función","voz":true,"colVoz":1,"encabezados":["Función","Ejemplo","Español"],"filas":[["Añadir","On top of that, shipping costs went up.","Encima de eso, subieron los costos de envío."],["Añadir","What's more, the client loved the design.","Además, al cliente le encantó el diseño."],["Contrastar","Having said that, we still need more data.","Dicho esto, todavía necesitamos más datos."],["Contrastar","On the other hand, it's a big investment.","Por otro lado, es una inversión grande."],["Aclarar","In other words, we're out of budget.","En otras palabras, ya no tenemos presupuesto."],["Ir al punto","The thing is, we don't have enough people.","El detalle es que no tenemos suficiente gente."],["Admitir algo","Admittedly, the first version wasn't perfect.","Hay que reconocer que la primera versión no era perfecta."],["Concluir","All in all, it was a great year.","En general, fue un gran año."]]},{"tipo":"comparar","titulo":"Errores comunes con los marcadores","malTitulo":"Evita","mal":"<i><b>In the other hand</b>, it's expensive.</i><br><i><b>At the end</b>, we decided to wait.</i> (queriendo decir «al final»)<br><i><b>Resuming</b>, we need more time.</i>","bienTitulo":"Correcto","bien":"<i><b>On</b> the other hand, it's expensive.</i><br><i><b>In the end</b>, we decided to wait.</i> (<i>at the end</i> + <i>of</i> algo: <i>at the end of the meeting</i>)<br><i><b>To sum up</b>, we need more time.</i> (<i>resume</i> = reanudar)"},{"tipo":"relacionar","rotulo":"Relaciona el marcador con su función","pares":[["On top of that","Añadir otra idea"],["Having said that","Matizar lo que acabas de decir"],["In other words","Decirlo de otra forma"],["All in all","Concluir con una idea general"],["Admittedly","Reconocer un punto débil"],["The thing is","Ir al problema de fondo"]]},{"tipo":"completar","rotulo":"Completa con el marcador","voz":true,"items":[{"frase":"The hotel is beautiful. ___ said that, it's a bit far from the beach.","resp":["Having"],"es":"El hotel es precioso. Dicho esto, está un poco lejos de la playa."},{"frase":"We lost the client. On ___ of that, the truck broke down.","resp":["top"],"es":"Perdimos al cliente. Encima de eso, se descompuso el camión."},{"frase":"Sales fell 40%. In ___ words, we had a terrible quarter.","resp":["other"],"es":"Las ventas cayeron 40 %. En otras palabras, tuvimos un trimestre terrible."},{"frase":"It was hard work, but all in ___, it was worth it.","resp":["all"],"es":"Fue mucho trabajo, pero en general valió la pena."},{"frase":"In the ___, we chose the local supplier.","resp":["end"],"es":"Al final, elegimos al proveedor local."}]},{"tipo":"escuchar","rotulo":"Escucha y fíjate en el marcador","frases":[{"en":"The thing is, we don't have enough people.","pron":"de zing is ui dóunt jav inóf pípol","es":"El detalle es que no tenemos suficiente gente."},{"en":"Having said that, the results are promising.","pron":"jáving sed dat de risálts ar prómising","es":"Dicho esto, los resultados son prometedores."},{"en":"What's more, the client wants to double the order.","es":"Además, el cliente quiere duplicar el pedido."},{"en":"Admittedly, we made some mistakes at the beginning.","pron":"admítedli ui méid sam mistéiks","es":"Hay que reconocer que cometimos algunos errores al principio."}]},{"tipo":"clave","items":["Añadir: <i>on top of that, what's more</i> · Contrastar: <i>having said that, on the other hand</i>.","Aclarar: <i>in other words</i> · Ir al punto: <i>the thing is</i> · Concluir: <i>all in all</i>.","<i>In the end</i> = al final (por fin) · <i>at the end of</i> + algo.","<i>Resume</i> = reanudar; para resumir usa <i>to sum up</i>."]}],"c-ingles-b2-m3-l4":[{"tipo":"texto","texto":"En un reporte mensual o una junta de resultados no basta con decir <i>sales went up</i>. Un hablante B2 dice <b>cuánto</b>, <b>qué tan rápido</b> y <b>por qué</b>: <i>Sales <b>rose sharply by 18%</b> in March, <b>mainly due to</b> the Easter holidays.</i> Tienes dos formas de decirlo: con <b>verbo + adverbio</b> (<i>rose sharply</i>) o con <b>adjetivo + sustantivo</b> (<i>a sharp rise</i>)."},{"tipo":"tabla","titulo":"Verbos y sustantivos de tendencia","voz":true,"colVoz":1,"encabezados":["Movimiento","Ejemplo","Español"],"filas":[["Subir","Exports rose sharply in the first quarter.","Las exportaciones subieron mucho en el primer trimestre."],["Subir (sustantivo)","There was a steady increase in bookings.","Hubo un aumento constante en las reservaciones."],["Bajar","Costs fell slightly after the new contract.","Los costos bajaron un poco después del nuevo contrato."],["Bajar (sustantivo)","We saw a dramatic drop in complaints.","Vimos una caída drástica en las quejas."],["Máximo","Sales peaked in December.","Las ventas llegaron a su punto máximo en diciembre."],["Estabilizarse","Prices leveled off in the summer.","Los precios se estabilizaron en el verano."],["Subir y bajar","The exchange rate fluctuated all year.","El tipo de cambio fluctuó todo el año."]],"nota":"Adverbios de más a menos: <i>dramatically, sharply, significantly, steadily, gradually, slightly</i>. En Reino Unido se escribe <i>levelled off</i>."},{"tipo":"comparar","titulo":"Preposiciones que cambian el dato","malTitulo":"Evita","mal":"<i>Sales increased <b>in</b> 10%.</i><br><i>Sales went from 200 <b>until</b> 300 units.</i><br><i>There was an increase <b>of</b> sales.</i><br><i>15 <b>percents</b></i>","bienTitulo":"Correcto","bien":"<i>Sales increased <b>by</b> 10%.</i> (la diferencia)<br><i>Sales went up <b>from</b> 200 <b>to</b> 300 units.</i><br><i>There was an increase <b>in</b> sales <b>of</b> 10%.</i><br><i>15 <b>percent</b></i> (sin <i>s</i>)"},{"tipo":"tarjetas","rotulo":"Adjetivo + sustantivo","voz":true,"instruccion":"Ves el verbo con adverbio; di la versión con sustantivo antes de voltear.","tarjetas":[{"frente":"rose sharply","reverso":"a sharp rise","ej":"There was a sharp rise in fuel prices."},{"frente":"fell slightly","reverso":"a slight fall","ej":"We saw a slight fall in demand."},{"frente":"increased steadily","reverso":"a steady increase","ej":"There has been a steady increase in tourism."},{"frente":"dropped dramatically","reverso":"a dramatic drop","ej":"There was a dramatic drop in orders."},{"frente":"grew gradually","reverso":"gradual growth","ej":"The company has seen gradual growth."}]},{"tipo":"practica","rotulo":"Describe la gráfica","preguntas":[{"p":"Las ventas pasaron de 100 a 130. <i>Sales increased ___ 30%.</i>","ops":["in","by","of"],"correcta":1},{"p":"Subieron muchísimo en muy poco tiempo:","ops":["Sales rose slightly.","Sales leveled off.","Sales rose sharply."],"correcta":2},{"p":"Llegaron a su punto más alto en agosto:","ops":["They peaked in August.","They fluctuated in August.","They dropped in August."],"correcta":0},{"p":"«Hubo un ligero aumento en los costos»","ops":["There was a slight increase of the costs.","There was a slight increase in costs.","There was a slightly increase in costs."],"correcta":1,"explica":"Con sustantivo va <b>adjetivo</b> (<i>slight</i>) y la preposición <b>in</b>."},{"p":"Subía y bajaba sin un patrón claro:","ops":["It fluctuated.","It peaked.","It leveled off."],"correcta":0}]},{"tipo":"completar","rotulo":"Completa el reporte","voz":true,"items":[{"frase":"Bookings went up ___ 1,200 to 1,500 in July.","resp":["from"],"es":"Las reservaciones subieron de 1,200 a 1,500 en julio."},{"frase":"There was a sharp ___ in complaints after the new policy.","resp":["drop","fall","decrease","decline"],"es":"Hubo una caída brusca en las quejas después de la nueva política."},{"frase":"Prices fell ___ (slight) in the second quarter.","resp":["slightly"],"es":"Los precios bajaron un poco en el segundo trimestre."},{"frase":"Sales peaked in December, mainly due ___ the holidays.","resp":["to"],"es":"Las ventas llegaron a su máximo en diciembre, sobre todo por las fiestas."},{"frase":"After the spike, demand leveled ___ at around 500 units.","resp":["off","out"],"es":"Después del pico, la demanda se estabilizó en unas 500 unidades."}]},{"tipo":"pronunciar","rotulo":"Lee cifras como en una junta","frases":[{"en":"Sales rose by three point five percent.","pron":"séils róus bai zri póint fáiv persént","es":"Las ventas subieron 3.5 %."},{"en":"We reached one point two million users.","pron":"ui richt uán póint tu mílion iúsers","es":"Llegamos a 1.2 millones de usuarios."},{"en":"There was a dramatic drop in complaints.","es":"Hubo una caída drástica en las quejas."},{"en":"Prices leveled off in the summer.","pron":"práises lévold of in de sámer","es":"Los precios se estabilizaron en el verano."}]},{"tipo":"clave","items":["<i>rise, increase, fall, drop, peak, level off, fluctuate</i>.","Verbo + adverbio (<i>rose sharply</i>) o adjetivo + sustantivo (<i>a sharp rise</i>).","<b>by</b> = la diferencia · <b>from… to…</b> = el antes y el después · <i>an increase <b>in</b></i>.","Di siempre cuánto y por qué: <i>…mainly due to…</i>"]}],"c-ingles-b2-m3-l5":[{"tipo":"texto","texto":"La parte que más nervios da de una presentación no es hablar: son las <b>preguntas</b>. La buena noticia es que casi todas las situaciones se resuelven con pocas frases: <b>ganar tiempo</b> para pensar, <b>confirmar</b> que entendiste, <b>admitir</b> con honestidad que no tienes un dato (y prometer enviarlo), <b>redirigir</b> lo que no toca y <b>verificar</b> que respondiste. Nadie espera que lo sepas todo; esperan que respondas con profesionalismo."},{"tipo":"tabla","titulo":"Frases para la sesión de preguntas","voz":true,"colVoz":1,"encabezados":["Situación","Frase","Español"],"filas":[["Ganar tiempo","That's a good question. Let me think about that for a second.","Buena pregunta. Déjame pensarlo un segundo."],["Confirmar","If I understand you correctly, you're asking about the costs.","Si te entiendo bien, preguntas por los costos."],["No entendiste","Sorry, could you rephrase the question?","Perdón, ¿podrías plantear la pregunta de otra forma?"],["No tienes el dato","I don't have that figure with me, but I'll get back to you by Friday.","No traigo ese dato, pero te lo mando a más tardar el viernes."],["Fuera de tema","That's slightly outside the scope of today's talk.","Eso queda un poco fuera del alcance de la presentación de hoy."],["Pregunta hostil","I can see why you'd think that. Let me explain our reasoning.","Entiendo por qué lo piensas. Déjame explicar nuestro razonamiento."],["Verificar","Does that answer your question?","¿Con eso respondo tu pregunta?"]],"nota":"Nunca inventes un dato. <i>I'll get back to you</i> es una promesa: cúmplela."},{"tipo":"dialogo","titulo":"Diálogo — Preguntas después de presentar un proyecto de expansión en Monterrey","lineas":[{"quien":"Mr. Walsh","en":"You said the new warehouse will pay for itself in two years. Isn't that a bit optimistic?","es":"Dijiste que el nuevo almacén se paga solo en dos años. ¿No es un poco optimista?"},{"quien":"Fernanda","en":"I can see why you'd think that. Let me explain how we got that number.","es":"Entiendo por qué lo piensas. Déjame explicar cómo llegamos a esa cifra."},{"quien":"Fernanda","en":"It assumes we keep our three biggest clients, which have all renewed until 2028.","es":"Supone que conservamos a nuestros tres clientes más grandes, que ya renovaron hasta 2028."},{"quien":"Ms. Kim","en":"What about the cost of electricity in the region?","es":"¿Y el costo de la electricidad en la región?"},{"quien":"Fernanda","en":"Good question. I don't have the exact figure with me, but I'll get back to you by Friday.","es":"Buena pregunta. No traigo la cifra exacta, pero te la mando a más tardar el viernes."},{"quien":"Fernanda","en":"Does that answer your question, Mr. Walsh?","es":"¿Con eso respondo su pregunta, Mr. Walsh?"},{"quien":"Mr. Walsh","en":"It does, thanks. That's very clear.","es":"Sí, gracias. Muy claro."}]},{"tipo":"practica","rotulo":"¿Qué respondes?","preguntas":[{"p":"Te preguntan un dato que no sabes.","ops":["I think it's about 20%, more or less, I guess.","I don't have that figure with me, but I'll get back to you.","That's not important."],"correcta":1},{"p":"No entendiste bien la pregunta.","ops":["What?","Sorry, could you rephrase the question?","Repeat."],"correcta":1},{"p":"La pregunta no tiene que ver con tu tema.","ops":["That's slightly outside the scope of today's talk.","Bad question.","I don't want to answer."],"correcta":0},{"p":"¿Cómo reacciona Fernanda a la pregunta hostil?","ops":["Se defiende atacando","Reconoce la duda y explica su razonamiento","Cambia de tema"],"correcta":1},{"p":"<i>I'll get back to you</i> significa…","ops":["Voy a regresar a mi lugar","Te doy la espalda","Te respondo después"],"correcta":2}]},{"tipo":"ordenar","rotulo":"Arma las respuestas","voz":true,"items":[{"frase":"Let me think about that for a second","es":"Déjame pensarlo un segundo"},{"frase":"I'll get back to you by Friday","es":"Te respondo a más tardar el viernes"},{"frase":"Could you rephrase the question?","es":"¿Podrías plantear la pregunta de otra forma?"},{"frase":"Does that answer your question?","es":"¿Con eso respondo tu pregunta?"}]},{"tipo":"pronunciar","rotulo":"Responde con calma","frases":[{"en":"I can see why you'd think that.","pron":"ai can si uái iud zink dat","es":"Entiendo por qué lo piensas."},{"en":"If I understand you correctly, you're asking about costs.","es":"Si te entiendo bien, preguntas por los costos."},{"en":"That's slightly outside the scope of today's talk.","pron":"dats sláitli autsáid de scóup ov tudéis tok","es":"Eso queda un poco fuera del alcance de la presentación de hoy."}]},{"tipo":"reflexion","rotulo":"Prepara tu sesión de preguntas","pregunta":"Piensa en una presentación real o posible de tu trabajo. Escribe las tres preguntas más difíciles que te podrían hacer y tu respuesta a cada una en inglés, usando al menos una frase de esta lección en cada respuesta.","ayuda":"That's a good question… / I can see why you'd think that… / I don't have that figure with me, but… / Does that answer your question?"},{"tipo":"clave","items":["Gana tiempo sin pena: <i>Let me think about that for a second.</i>","Confirma antes de responder: <i>If I understand you correctly…</i>","Si no sabes, no inventes: <i>I'll get back to you by…</i>, y cúmplelo.","Cierra cada respuesta con <i>Does that answer your question?</i> Pasa a la evaluación: necesitas 80%."]}],"c-ingles-b2-m4-l1":[{"tipo":"texto","texto":"En el B2 ya no escribes solo con <i>and, but, because</i>. Un informe o una propuesta necesita conectores más precisos. El truco no es aprenderte la lista: es saber <b>qué va después de cada uno</b>. Algunos van seguidos de una <b>oración completa</b> (sujeto + verbo): <i>although, even though, whereas</i>. Otros van seguidos de un <b>sustantivo o un verbo en -ing</b>: <i>despite, in spite of, due to, owing to</i>. Y otros <b>empiezan una oración nueva</b> y llevan coma: <i>However, Nevertheless, Therefore, Moreover</i>."},{"tipo":"tabla","titulo":"Conectores y su estructura","voz":true,"colVoz":1,"encabezados":["Conector","Ejemplo","Estructura"],"filas":[["although / even though","Although the price was high, we accepted the offer.","+ sujeto + verbo"],["despite / in spite of","Despite the high price, we accepted the offer.","+ sustantivo o -ing"],["whereas","Our plant runs two shifts, whereas theirs runs three.","Contraste entre dos cosas"],["nevertheless / however","The project was expensive. Nevertheless, it paid off.","Oración nueva + coma"],["due to / owing to","The flight was cancelled due to bad weather.","+ sustantivo"],["therefore / consequently","Demand fell. Therefore, we reduced production.","Oración nueva: consecuencia"],["moreover / furthermore","The system is faster. Moreover, it is cheaper.","Oración nueva: añade"],["in addition to","In addition to reducing costs, it saves time.","+ sustantivo o -ing"]],"nota":"<i>Despite the fact that</i> + oración también existe: <i>Despite the fact that the price was high…</i> Es más formal que <i>although</i>."},{"tipo":"comparar","titulo":"Los errores que más delatan al hispanohablante","malTitulo":"Evita","mal":"<i><b>Despite of</b> the delay, we finished.</i><br><i><b>Although</b> the rain, we traveled.</i><br><i>The price is high, <b>however</b> the quality is good.</i><br><i>In addition to <b>reduce</b> costs…</i>","bienTitulo":"Correcto","bien":"<i><b>Despite</b> the delay / <b>In spite of</b> the delay, we finished.</i><br><i><b>Despite</b> the rain, we traveled. / <b>Although</b> it was raining…</i><br><i>The price is high. <b>However</b>, the quality is good.</i><br><i>In addition to <b>reducing</b> costs…</i>"},{"tipo":"practica","rotulo":"Elige el conector correcto","preguntas":[{"p":"___ the strike, the plant kept running.","ops":["Although","Despite","However"],"correcta":1,"explica":"Después viene un sustantivo (<i>the strike</i>) → <b>despite</b>."},{"p":"___ we had a small team, we met the deadline.","ops":["Although","Despite","Due to"],"correcta":0},{"p":"The Monterrey office is growing, ___ the Puebla office is shrinking.","ops":["therefore","whereas","moreover"],"correcta":1},{"p":"Fuel prices rose. ___, we had to increase our rates.","ops":["Consequently","Whereas","Despite"],"correcta":0},{"p":"¿Cuál es correcta?","ops":["In spite of we worked hard, we lost.","Despite of working hard, we lost.","Despite working hard, we lost."],"correcta":2}]},{"tipo":"completar","rotulo":"Completa el informe","voz":true,"items":[{"frase":"The shipment was delayed ___ to a problem at customs.","resp":["due","owing"],"es":"El envío se retrasó por un problema en la aduana."},{"frase":"In spite ___ the crisis, sales remained stable.","resp":["of"],"es":"A pesar de la crisis, las ventas se mantuvieron estables."},{"frase":"The proposal is expensive. ___, it is the best option.","resp":["Nevertheless","However","Nonetheless"],"es":"La propuesta es cara. Aun así, es la mejor opción."},{"frase":"Even ___ the hotel was full, they found us a room.","resp":["though"],"es":"Aunque el hotel estaba lleno, nos consiguieron una habitación."},{"frase":"The new software is easier to use. ___, it requires less training.","resp":["Moreover","Furthermore","In addition","Therefore","Consequently"],"es":"El software nuevo es más fácil de usar. Además, requiere menos capacitación."}]},{"tipo":"ordenar","rotulo":"Arma la frase","voz":true,"items":[{"frase":"Despite the delay, the client was satisfied","es":"A pesar del retraso, el cliente quedó satisfecho"},{"frase":"Demand fell. Therefore, we reduced production","es":"La demanda bajó. Por lo tanto, redujimos la producción"},{"frase":"Although it was expensive, it paid off","es":"Aunque fue caro, valió la pena"}]},{"tipo":"clave","items":["<b>although / even though / whereas</b> + oración completa.","<b>despite / in spite of / due to</b> + sustantivo o -ing. Nunca «despite of».","<b>However, Nevertheless, Therefore, Moreover</b> empiezan oración y llevan coma.","En un texto formal, varía los conectores: no uses <i>but</i> cinco veces."]}],"c-ingles-b2-m4-l2":[{"tipo":"texto","texto":"En el B1 usaste la pasiva para explicar procesos (<i>The orders are shipped on Monday</i>). En los informes y correos profesionales la necesitas en <b>todos los tiempos</b>, con <b>modales</b> y en su forma <b>impersonal</b>, que es la manera de decir «se espera que», «se cree que» o «se dice que» sin mencionar quién lo piensa. Es la voz de los informes: objetiva, sin culpar y sin opiniones personales."},{"tipo":"tabla","titulo":"La pasiva en todas sus formas","voz":true,"colVoz":1,"encabezados":["Forma","Ejemplo","Español"],"filas":[["Presente continuo","The contract is being reviewed by legal.","Jurídico está revisando el contrato."],["Present perfect","The budget has been approved.","Ya se aprobó el presupuesto."],["Modal","All visitors must be registered at the gate.","Todos los visitantes deben registrarse en la entrada."],["Modal en pasado","The invoice should have been sent last week.","La factura se debió haber enviado la semana pasada."],["Dos objetos","We were given a new deadline.","Nos dieron una nueva fecha límite."],["Impersonal (it)","It is expected that prices will rise.","Se espera que los precios suban."],["Impersonal (sujeto)","The new plant is expected to open in March.","Se espera que la nueva planta abra en marzo."],["Impersonal (pasado)","The fire is believed to have started in the warehouse.","Se cree que el incendio empezó en el almacén."]],"nota":"Verbos típicos de la forma impersonal: <i>expect, believe, say, report, estimate, consider, think</i>."},{"tipo":"comparar","titulo":"Calcos del «se» español","malTitulo":"Evita","mal":"<i><b>It was informed us</b> that the meeting was cancelled.</i><br><i><b>Is said</b> that the company will close.</i><br><i>The report <b>has been finish</b>.</i>","bienTitulo":"Correcto","bien":"<i><b>We were informed</b> that the meeting had been cancelled.</i><br><i><b>It is said</b> that the company will close. / The company <b>is said to</b> be closing.</i><br><i>The report <b>has been finished</b>.</i> (siempre participio)"},{"tipo":"practica","rotulo":"Elige la pasiva correcta","preguntas":[{"p":"«Están revisando tu solicitud» (ahora mismo):","ops":["Your application is being reviewed.","Your application is reviewed.","Your application has being reviewed."],"correcta":0},{"p":"«Se cree que el problema empezó el lunes»:","ops":["The problem is believed to start on Monday.","The problem is believed to have started on Monday.","It believes the problem started on Monday."],"correcta":1,"explica":"Para algo anterior se usa <b>to have + participio</b>."},{"p":"«Nos informaron del cambio»:","ops":["It was informed us of the change.","Us were informed of the change.","We were informed of the change."],"correcta":2},{"p":"«El pago se debió haber hecho ayer»:","ops":["The payment should have been made yesterday.","The payment should be made yesterday.","The payment must have made yesterday."],"correcta":0},{"p":"«Se espera que las ventas suban 5 %»:","ops":["Sales are expected to rise by 5%.","Sales expect to rise by 5%.","It is expecting that sales rise 5%."],"correcta":0}]},{"tipo":"completar","rotulo":"Completa con la pasiva","voz":true,"items":[{"frase":"The new equipment is ___ (install) this week.","resp":["being installed"],"es":"Están instalando el equipo nuevo esta semana."},{"frase":"All the samples have ___ (test) in our lab.","resp":["been tested"],"es":"Todas las muestras se han probado en nuestro laboratorio."},{"frase":"Safety glasses must ___ (wear) at all times.","resp":["be worn"],"es":"Se deben usar lentes de seguridad en todo momento."},{"frase":"It is ___ that the project will cost 2 million pesos.","resp":["estimated","expected","believed"],"es":"Se estima que el proyecto costará 2 millones de pesos."},{"frase":"The CEO is said ___ resigned last night.","resp":["to have"],"es":"Se dice que el director general renunció anoche."}]},{"tipo":"escuchar","rotulo":"Escucha frases de informe","frases":[{"en":"The budget has already been approved.","pron":"de báyet jas olrédi bin aprúvd","es":"El presupuesto ya se aprobó."},{"en":"Your request is being processed.","pron":"iur ricuést is bíing prósest","es":"Tu solicitud se está procesando."},{"en":"The new route is expected to reduce delivery times.","es":"Se espera que la nueva ruta reduzca los tiempos de entrega."},{"en":"We were given two extra weeks.","es":"Nos dieron dos semanas extra."}]},{"tipo":"clave","items":["Pasiva = <b>be</b> en el tiempo que necesites + participio: <i>is being done, has been done, should have been done</i>.","Con dos objetos, la persona puede ser sujeto: <i>We were given…</i>","Impersonal: <i>It is expected that…</i> o <i>X is expected to…</i>","Para algo anterior: <i>is believed <b>to have</b> started</i>."]}],"c-ingles-b2-m4-l3":[{"tipo":"texto","texto":"En español decimos «me corté el pelo» aunque lo haya hecho el peluquero, o «arreglamos el techo» aunque haya venido un contratista. En inglés eso suena a que <b>tú mismo</b> lo hiciste. Cuando otra persona hace el trabajo por ti, se usa el <b>causativo</b>: <b>have + objeto + participio</b> (<i>I <b>had my hair cut</b></i>). <b>get</b> funciona igual y es un poco más informal."},{"tipo":"tabla","titulo":"Las cuatro formas del causativo","voz":true,"colVoz":1,"encabezados":["Estructura","Ejemplo","Español"],"filas":[["have + cosa + participio","We had the machines serviced last month.","Mandamos dar mantenimiento a las máquinas el mes pasado."],["get + cosa + participio","I need to get my passport renewed.","Tengo que renovar mi pasaporte."],["have + persona + verbo","I'll have my assistant send you the file.","Le voy a pedir a mi asistente que te mande el archivo."],["get + persona + to + verbo","Can you get the supplier to lower the price?","¿Puedes conseguir que el proveedor baje el precio?"],["En pasiva de mala suerte","We had our laptops stolen at the airport.","Nos robaron las laptops en el aeropuerto."]],"nota":"Ojo: <i>get someone <b>to</b> do</i> lleva <i>to</i>; <i>have someone do</i> no."},{"tipo":"comparar","titulo":"Cuando el español te engaña","malTitulo":"Suena a que lo hiciste tú","mal":"<i>I <b>cut my hair</b> yesterday.</i> (lo hizo el peluquero)<br><i>We <b>painted</b> the office.</i> (vino un pintor)<br><i>I'll get the report <b>translate</b>.</i>","bienTitulo":"Correcto","bien":"<i>I <b>had my hair cut</b> yesterday.</i><br><i>We <b>had the office painted</b>.</i><br><i>I'll get the report <b>translated</b>.</i> (participio)"},{"tipo":"dialogo","titulo":"Diálogo — Preparando una auditoría en una planta de Saltillo","lineas":[{"quien":"Jorge","en":"The auditors arrive on Monday. Is everything ready?","es":"Los auditores llegan el lunes. ¿Está todo listo?"},{"quien":"Patricia","en":"Almost. We had the fire extinguishers checked yesterday.","es":"Casi. Ayer mandamos revisar los extintores."},{"quien":"Jorge","en":"Good. What about the scales in the lab?","es":"Bien. ¿Y las básculas del laboratorio?"},{"quien":"Patricia","en":"We're getting them calibrated tomorrow. I'll have the technician send you the certificates.","es":"Mañana las mandamos calibrar. Le voy a pedir al técnico que te mande los certificados."},{"quien":"Jorge","en":"Perfect. And the procedures manual?","es":"Perfecto. ¿Y el manual de procedimientos?"},{"quien":"Patricia","en":"I got Carlos to update it, and we're having it translated into English.","es":"Conseguí que Carlos lo actualizara, y lo estamos mandando traducir al inglés."}]},{"tipo":"practica","rotulo":"¿Quién hizo el trabajo?","preguntas":[{"p":"<i>We had the roof repaired.</i> ¿Quién reparó el techo?","ops":["Nadie: solo planeamos repararlo","Nosotros mismos","Nosotros, con ayuda de un vecino","Otra persona que contratamos"],"correcta":3,"explica":"<i>Have something done</i> significa que otra persona lo hizo por ti, normalmente porque la contrataste; además, ya ocurrió."},{"p":"«Me voy a hacer un examen de la vista»:","ops":["I'm going to test my eyes.","I'm going to have my eyes tested.","I'm going to have tested my eyes."],"correcta":1},{"p":"Can you get the IT team ___ my password?","ops":["reset","to reset","resetting"],"correcta":1,"explica":"<i>get + persona + <b>to</b> + verbo</i>."},{"p":"I'll have my assistant ___ you the details.","ops":["send","to send","sent"],"correcta":0},{"p":"«Le robaron la cartera en el metro»:","ops":["He stole his wallet on the subway.","His wallet stole on the subway.","He had his wallet stolen on the subway."],"correcta":2}]},{"tipo":"completar","rotulo":"Completa con el causativo","voz":true,"items":[{"frase":"We need to get the contract ___ (review) by a lawyer.","resp":["reviewed"],"es":"Tenemos que mandar revisar el contrato con un abogado."},{"frase":"I ___ my car washed while I was in the meeting.","resp":["had","got"],"es":"Mandé lavar el coche mientras estaba en la junta."},{"frase":"She got her manager ___ approve the vacation.","resp":["to"],"es":"Consiguió que su gerente le aprobara las vacaciones."},{"frase":"We're having new uniforms ___ (make) for the hotel staff.","resp":["made"],"es":"Estamos mandando hacer uniformes nuevos para el personal del hotel."}]},{"tipo":"ordenar","rotulo":"Arma la frase","voz":true,"items":[{"frase":"We had the machines serviced last month","es":"Mandamos dar mantenimiento a las máquinas el mes pasado"},{"frase":"I need to get my visa renewed","es":"Tengo que renovar mi visa"},{"frase":"I'll have Laura call you back","es":"Le voy a pedir a Laura que te regrese la llamada"}]},{"tipo":"clave","items":["Otra persona lo hace por ti: <b>have / get + cosa + participio</b>.","<i>I had my hair cut</i>, no «I cut my hair» (si fue el peluquero).","<b>have someone do</b> · <b>get someone to do</b>.","También sirve para cosas malas que te pasan: <i>We had our laptops stolen.</i>"]}],"c-ingles-b2-m4-l4":[{"tipo":"texto","texto":"Tu jefe en Estados Unidos o Canadá probablemente va a leer solo el primer párrafo de tu informe. Por eso los informes en inglés empiezan con un <b>executive summary</b>: la conclusión y la recomendación <b>primero</b>, los detalles después. Es al revés de como solemos escribir en español, donde contamos todo el contexto antes de llegar al punto. Además, se usan títulos, viñetas y oraciones cortas."},{"tipo":"pasos","rotulo":"Estructura de un informe breve","pasos":["<b>Executive summary:</b> en 3 o 4 líneas, qué encontraste y qué recomiendas. <i>This report recommends switching to a local supplier.</i>","<b>Background:</b> por qué se hizo el informe. <i>In May, defect rates rose to 4%.</i>","<b>Findings:</b> los datos, con viñetas y sin opiniones. <i>It was found that 70% of defects came from one batch.</i>","<b>Recommendations:</b> qué hacer, con verbos claros. <i>We recommend that the company audit all suppliers.</i>","<b>Next steps:</b> quién hace qué y para cuándo. <i>The purchasing team will contact two new suppliers by June 15.</i>"]},{"tipo":"tabla","titulo":"Frases de informes y propuestas","voz":true,"colVoz":1,"encabezados":["Uso","Frase","Español"],"filas":[["Propósito","The purpose of this report is to assess our delivery times.","El propósito de este informe es evaluar nuestros tiempos de entrega."],["Hallazgo","It was found that most delays occurred on Mondays.","Se encontró que la mayoría de los retrasos ocurrían los lunes."],["Datos","According to the data, costs rose by 12%.","Según los datos, los costos subieron 12 %."],["Recomendar","We recommend that the company invest in new software.","Recomendamos que la empresa invierta en software nuevo."],["Proponer","We propose a six-month pilot in the Querétaro branch.","Proponemos un piloto de seis meses en la sucursal de Querétaro."],["Concluir","Based on these findings, we suggest the following steps.","Con base en estos hallazgos, sugerimos los siguientes pasos."]],"nota":"Después de <i>recommend that</i> y <i>suggest that</i>, el verbo va en forma base, sin <i>-s</i>: <i>that the company <b>invest</b></i>."},{"tipo":"comparar","titulo":"De borrador informal a registro de informe","malTitulo":"Borrador","mal":"<i>We looked at a lot of stuff and we think the supplier isn't good.</i><br><i>Things got better.</i><br><i>We should maybe get new trucks.</i>","bienTitulo":"Informe","bien":"<i>An analysis of 200 orders shows that the supplier consistently misses deadlines.</i><br><i>On-time deliveries improved from 82% to 95%.</i><br><i>We recommend replacing three trucks in Q3.</i>"},{"tipo":"plantilla","rotulo":"Modelo — Resumen ejecutivo de un informe","texto":"Subject: Report – Delivery delays at the Guadalajara distribution center\n\nExecutive summary\nThis report analyzes the delivery delays recorded between January and March. It was found that 68% of late deliveries were caused by a shortage of drivers on weekends. We recommend that the company hire four part-time drivers and adjust the weekend schedule.\n\nBackground\nIn January, on-time deliveries fell from 94% to 81%, and two major clients complained.\n\nFindings\n• Most delays occurred on Saturdays and Sundays.\n• Despite higher demand, the number of weekend drivers had not changed since 2023.\n• Fuel and traffic had only a minor impact.\n\nRecommendations\n• Hire four part-time drivers for weekends.\n• Review the schedule every quarter.\n\nNext steps\nHuman Resources will publish the job openings by April 10.","nota":"Observa: la recomendación va desde el primer párrafo, los hallazgos van en viñetas y hay pasiva (<i>it was found, were caused</i>), conectores (<i>despite</i>) y past perfect (<i>had not changed</i>)."},{"tipo":"practica","rotulo":"¿Entendiste el modelo?","preguntas":[{"p":"¿Qué va en el <i>executive summary</i>?","ops":["Todo el contexto histórico de la empresa","El hallazgo principal y la recomendación","Solo los agradecimientos"],"correcta":1},{"p":"Según el informe, ¿cuál fue la causa principal de los retrasos?","ops":["El tráfico","El precio del combustible","La falta de choferes en fin de semana"],"correcta":2},{"p":"¿Cuál es correcta?","ops":["We recommend that the company hires more staff.","We recommend that the company hire more staff.","We recommend the company to hiring more staff."],"correcta":1},{"p":"La versión de informe de <i>Things got better</i> es…","ops":["Things got much more better.","On-time deliveries improved from 82% to 95%.","Things are good now, we think."],"correcta":1},{"p":"<i>Next steps</i> debe decir…","ops":["Quién hace qué y para cuándo","Una opinión personal","Un resumen de la historia"],"correcta":0}]},{"tipo":"reflexion","rotulo":"Tu propio resumen ejecutivo","pregunta":"Piensa en un problema real de tu trabajo o tu negocio. Escribe en inglés un <i>executive summary</i> de 3 a 4 oraciones: qué analizaste, qué encontraste (con un dato) y qué recomiendas. Usa al menos una pasiva y un <i>We recommend that…</i>","ayuda":"This report analyzes… / It was found that… / We recommend that the company…"},{"tipo":"clave","items":["La conclusión y la recomendación van <b>primero</b>, en el <i>executive summary</i>.","Estructura: summary → background → findings → recommendations → next steps.","Datos concretos en vez de <i>a lot of, things, stuff</i>.","<i>We recommend that + sujeto + verbo base</i>: <i>that the company invest</i>."]}],"c-ingles-b2-m4-l5":[{"tipo":"texto","texto":"Hay correos que cuesta mucho escribir incluso en español. En inglés, la clave es la <b>estructura</b>: <b>1)</b> di de qué se trata desde la primera línea, <b>2)</b> explica los hechos sin emociones, <b>3)</b> di qué esperas o qué ofreces y <b>4)</b> cierra de forma cordial. Nada de disculpas en cada párrafo ni de mayúsculas o signos de exclamación: la firmeza está en la claridad, no en el tono."},{"tipo":"tabla","titulo":"Frases para cada correo difícil","voz":true,"colVoz":1,"encabezados":["Tipo","Frase","Español"],"filas":[["Queja","I am writing to express my concern regarding the quality of the last shipment.","Le escribo para expresar mi preocupación por la calidad del último envío."],["Queja: pedir solución","I would appreciate it if you could replace the damaged units by Friday.","Le agradecería que reemplazaran las unidades dañadas a más tardar el viernes."],["Disculpa","Please accept our apologies for the delay in your order.","Le ofrecemos una disculpa por el retraso en su pedido."],["Disculpa: responsabilidad","This was our mistake, and we have taken steps to prevent it from happening again.","Fue un error nuestro y ya tomamos medidas para que no se repita."],["Rechazo","After careful consideration, we have decided not to proceed with your proposal.","Después de analizarlo con cuidado, decidimos no seguir adelante con su propuesta."],["Rechazo: dejar la puerta abierta","We will keep your details on file for future projects.","Conservaremos sus datos para proyectos futuros."],["Recordatorio","I am writing to follow up on invoice #4521, which was due on May 3.","Le escribo para dar seguimiento a la factura #4521, que vencía el 3 de mayo."],["Recordatorio firme","We would be grateful if payment could be made within seven days.","Le agradeceríamos que el pago se realizara en un plazo de siete días."]]},{"tipo":"comparar","titulo":"Errores que restan profesionalismo","malTitulo":"Evita","mal":"<i>Sorry for the <b>inconveniences</b>.</i><br><i>We are <b>very very sorry</b>, sorry again!!</i><br><i>You <b>didn't pay</b> us. Pay now.</i><br><i>We apologize for <b>the late</b>.</i>","bienTitulo":"Correcto","bien":"<i>We apologize for <b>the inconvenience</b>.</i><br><i>We <b>sincerely apologize</b>.</i> (una sola vez, bien dicha)<br><i>Our records show that the payment <b>has not been received</b>.</i><br><i>We apologize for <b>the delay</b>.</i>"},{"tipo":"plantilla","rotulo":"Modelo — Rechazar una propuesta con cortesía","texto":"Subject: Your proposal for cleaning services\n\nDear Ms. Turner,\n\nThank you for your proposal and for taking the time to visit our hotel in Playa del Carmen.\n\nAfter careful consideration, we have decided not to proceed with your proposal at this time. Although your service was highly rated, the price was above our budget for this year.\n\nWe were very impressed with your team, and we will keep your details on file for future projects.\n\nThank you again for your interest.\n\nKind regards,\n\nMariana López\nOperations Manager","nota":"Estructura: agradecer → decisión clara → razón breve (con <i>although</i>) → dejar la puerta abierta → cierre cordial."},{"tipo":"relacionar","rotulo":"¿Qué correo empieza así?","pares":[["I am writing to express my concern regarding…","Una queja formal"],["Please accept our apologies for…","Una disculpa"],["After careful consideration, we have decided not to…","Un rechazo"],["I am writing to follow up on invoice #4521…","Un recordatorio de pago"],["Thank you for your proposal and for your time.","Un agradecimiento inicial"]]},{"tipo":"practica","rotulo":"Elige la mejor opción","preguntas":[{"p":"Un cliente no ha pagado. ¿Cómo empiezas?","ops":["You didn't pay us!!","I am writing to follow up on invoice #4521, which was due on May 3.","Where is our money?"],"correcta":1},{"p":"¿Cuál es la disculpa más profesional?","ops":["Sorry sorry sorry for the inconveniences!","We sincerely apologize for the delay. We have taken steps to prevent it from happening again.","It was not our fault, but sorry."],"correcta":1},{"p":"En el modelo, ¿por qué rechazan la propuesta?","ops":["Porque el servicio era malo","Porque ya tenían otro proveedor","Porque el precio superaba su presupuesto"],"correcta":2},{"p":"<i>We will keep your details on file</i> sirve para…","ops":["Dejar la puerta abierta","Amenazar","Pedir un descuento"],"correcta":0}]},{"tipo":"completar","rotulo":"Completa los correos","voz":true,"items":[{"frase":"Please accept our ___ for the delay in your order.","resp":["apologies"],"es":"Le ofrecemos una disculpa por el retraso en su pedido."},{"frase":"After careful ___, we have decided not to proceed.","resp":["consideration"],"es":"Después de analizarlo con cuidado, decidimos no seguir adelante."},{"frase":"I would appreciate ___ if you could send a replacement.","resp":["it"],"es":"Le agradecería que enviaran un reemplazo."},{"frase":"Our records show that the payment has not ___ received.","resp":["been"],"es":"Nuestros registros indican que no se ha recibido el pago."}]},{"tipo":"clave","items":["Estructura: asunto claro → hechos → qué esperas u ofreces → cierre cordial.","Discúlpate una vez y bien: <i>We sincerely apologize…</i> + qué harás para que no se repita.","Rechaza con claridad y deja la puerta abierta: <i>We will keep your details on file.</i>","La firmeza está en la claridad, no en mayúsculas ni signos de exclamación. Pasa a la evaluación: necesitas 80%."]}],"c-ingles-b2-m5-l1":[{"tipo":"texto","texto":"Una <b>collocation</b> es una combinación de palabras que los nativos usan juntas «porque sí». En español «tomamos» una decisión; en inglés la <b>hacemos</b>: <i>make a decision</i>. En español la lluvia es «fuerte»; en inglés es <b>pesada</b>: <i>heavy rain</i>. Tu gramática puede ser perfecta, pero si dices <i>strong rain</i> o <i>make a question</i>, suenas a traducción. Aprende las palabras en <b>bloque</b>, no sueltas."},{"tipo":"tabla","titulo":"Collocations de trabajo","voz":true,"colVoz":1,"encabezados":["Verbo + sustantivo","Ejemplo","Español"],"filas":[["meet a deadline","We worked all weekend to meet the deadline.","Trabajamos todo el fin de semana para cumplir con la fecha límite."],["raise a concern","Several employees raised concerns about safety.","Varios empleados expresaron su preocupación por la seguridad."],["reach an agreement","We finally reached an agreement with the union.","Por fin llegamos a un acuerdo con el sindicato."],["place an order","The client placed an order for 5,000 units.","El cliente hizo un pedido de 5,000 unidades."],["address an issue","We need to address this issue immediately.","Tenemos que atender este problema de inmediato."],["gain experience","She gained a lot of experience in Canada.","Ganó mucha experiencia en Canadá."],["run a business","My parents run a small business in Puebla.","Mis papás tienen un pequeño negocio en Puebla."],["draw a conclusion","It's too early to draw any conclusions.","Es muy pronto para sacar conclusiones."]]},{"tipo":"comparar","titulo":"Calcos del español","malTitulo":"Evita","mal":"<i>Can I <b>make a question</b>?</i><br><i>I <b>did a mistake</b> in the report.</i><br><i>There was <b>strong rain</b> and <b>a lot of traffic</b>.</i><br><i>I <b>assisted</b> the meeting.</i><br><i>I <b>won</b> experience in sales.</i>","bienTitulo":"Natural","bien":"<i>Can I <b>ask a question</b>?</i><br><i>I <b>made a mistake</b> in the report.</i><br><i>There was <b>heavy rain</b> and <b>heavy traffic</b>.</i><br><i>I <b>attended</b> the meeting.</i> (<i>assist</i> = ayudar)<br><i>I <b>gained</b> experience in sales.</i>"},{"tipo":"tarjetas","rotulo":"Collocations para memorizar en bloque","voz":true,"instruccion":"Ves la collocation; di qué significa antes de voltear.","tarjetas":[{"frente":"meet a deadline","reverso":"cumplir con una fecha límite","ej":"We always meet our deadlines."},{"frente":"take a risk","reverso":"arriesgarse","ej":"Sometimes you have to take a risk."},{"frente":"raise a concern","reverso":"expresar una preocupación","ej":"I'd like to raise a concern about the budget."},{"frente":"place an order","reverso":"hacer un pedido","ej":"They placed an order yesterday."},{"frente":"heavy traffic","reverso":"mucho tráfico","ej":"Sorry I'm late. There was heavy traffic."},{"frente":"a tight deadline","reverso":"una fecha límite muy justa","ej":"We're working to a tight deadline."}]},{"tipo":"practica","rotulo":"Elige la collocation natural","preguntas":[{"p":"We need to ___ a decision by Friday.","ops":["do","make","take out"],"correcta":1},{"p":"Can I ___ a question about the schedule?","ops":["make","do","ask"],"correcta":2},{"p":"Sorry I'm late. The traffic was really ___.","ops":["heavy","strong","big"],"correcta":0},{"p":"«Asistí a una conferencia en Cancún»:","ops":["I assisted a conference in Cancún.","I attended a conference in Cancún.","I assisted to a conference in Cancún."],"correcta":1},{"p":"The two companies finally ___ an agreement.","ops":["reached","arrived","made up"],"correcta":0}]},{"tipo":"completar","rotulo":"Completa con el verbo que va","voz":true,"items":[{"frase":"If we don't hire more people, we won't ___ the deadline.","resp":["meet"],"es":"Si no contratamos más gente, no vamos a cumplir con la fecha límite."},{"frase":"The client ___ an order for three new machines.","resp":["placed"],"es":"El cliente hizo un pedido de tres máquinas nuevas."},{"frase":"Several workers ___ concerns about the night shift.","resp":["raised","expressed"],"es":"Varios trabajadores expresaron su preocupación por el turno nocturno."},{"frase":"It's too early to ___ conclusions.","resp":["draw","reach"],"es":"Es muy pronto para sacar conclusiones."},{"frase":"My aunt ___ a small restaurant in Oaxaca.","resp":["runs"],"es":"Mi tía tiene un pequeño restaurante en Oaxaca."}]},{"tipo":"clave","items":["Aprende palabras en bloque: <i>meet a deadline, reach an agreement, place an order</i>.","<i>make</i> a decision / a mistake · <i>ask</i> a question.","<i>heavy</i> rain / traffic, no «strong».","<i>attend</i> = asistir a · <i>assist</i> = ayudar · <i>gain</i> experience, no «win»."]}],"c-ingles-b2-m5-l2":[{"tipo":"texto","texto":"Los libros suelen enseñar idioms que ya nadie usa (<i>it's raining cats and dogs</i>). En las oficinas de Estados Unidos, Canadá o Reino Unido se oyen otros, todos los días. Tu objetivo principal es <b>entenderlos</b>, porque tus colegas nativos los van a usar. Para usarlos tú, elige tres o cuatro que te gusten y úsalos con naturalidad; <b>meter un idiom en cada frase</b> suena forzado."},{"tipo":"vocabulario","rotulo":"Idioms de oficina","palabras":[{"en":"on the same page","es":"en la misma sintonía, de acuerdo","ej":"Let's make sure we're all on the same page."},{"en":"a ballpark figure","es":"una cifra aproximada","ej":"Can you give me a ballpark figure?"},{"en":"get the ball rolling","es":"arrancar, poner algo en marcha","ej":"Let's get the ball rolling on the new project."},{"en":"back to square one","es":"volver a empezar desde cero","ej":"The client rejected the design, so we're back to square one."},{"en":"cut corners","es":"hacer las cosas a medias para ahorrar","ej":"We can't cut corners on safety."},{"en":"the bottom line","es":"lo esencial, el resultado final","ej":"The bottom line is that we need more clients."},{"en":"a steep learning curve","es":"algo que cuesta mucho aprender al principio","ej":"The new software has a steep learning curve."},{"en":"touch base","es":"ponerse en contacto brevemente","ej":"Let's touch base next week."},{"en":"go the extra mile","es":"hacer un esfuerzo extra","ej":"Our team always goes the extra mile for clients."},{"en":"call it a day","es":"dar por terminado el día","ej":"It's seven o'clock. Let's call it a day."}]},{"tipo":"dialogo","titulo":"Diálogo — Llamada semanal con el equipo de Phoenix desde una oficina en Hermosillo","lineas":[{"quien":"Kevin","en":"OK, let's get the ball rolling. Andrés, how's the new client portal going?","es":"Bueno, arranquemos. Andrés, ¿cómo va el nuevo portal de clientes?"},{"quien":"Andrés","en":"Well, the client changed the requirements, so we're almost back to square one.","es":"Pues el cliente cambió los requisitos, así que casi volvimos a empezar desde cero."},{"quien":"Kevin","en":"Ouch. Can you give me a ballpark figure for the new launch date?","es":"Uy. ¿Me puedes dar una fecha aproximada para el nuevo lanzamiento?"},{"quien":"Andrés","en":"Around mid-November. We could go faster, but we don't want to cut corners on testing.","es":"A mediados de noviembre. Podríamos ir más rápido, pero no queremos hacer las pruebas a medias."},{"quien":"Kevin","en":"Agreed. The bottom line is that it has to work on day one.","es":"De acuerdo. Lo esencial es que tiene que funcionar desde el primer día."},{"quien":"Andrés","en":"Exactly. I'll touch base with the client tomorrow to make sure we're on the same page.","es":"Exacto. Mañana me comunico con el cliente para asegurarme de que estemos en la misma sintonía."}]},{"tipo":"relacionar","rotulo":"Relaciona el idiom con su significado","voz":true,"pares":[["a ballpark figure","una cifra aproximada"],["back to square one","volver a empezar"],["cut corners","hacer las cosas a medias"],["touch base","comunicarse brevemente"],["call it a day","terminar por hoy"],["on the same page","estar de acuerdo, en sintonía"]]},{"tipo":"practica","rotulo":"¿Qué idiom usas?","preguntas":[{"p":"Tu jefe te pide un costo aproximado, no exacto.","ops":["Can you give me a ballpark figure?","Can you cut corners?","Let's call it a day."],"correcta":0},{"p":"El proyecto falló y hay que empezar de nuevo.","ops":["We're on the same page.","We're back to square one.","We went the extra mile."],"correcta":1},{"p":"Quieres asegurarte de que todos entendieron lo mismo.","ops":["Let's get the ball rolling.","Let's make sure we're all on the same page.","That's the bottom line."],"correcta":1},{"p":"<i>We can't cut corners on safety</i> significa…","ops":["No podemos recortar las esquinas","No podemos hacer a medias lo de la seguridad","No podemos hablar de seguridad"],"correcta":1},{"p":"¿Cuál es el mejor consejo sobre los idioms?","ops":["Usa uno en cada frase para impresionar","Entiéndelos todos y usa pocos, con naturalidad","Nunca los uses"],"correcta":1}]},{"tipo":"pronunciar","rotulo":"Dilos con naturalidad","frases":[{"en":"Let's get the ball rolling.","pron":"lets guet de bol róuling","es":"Arranquemos."},{"en":"Can you give me a ballpark figure?","pron":"can iu guiv mi a bólpark fíguiur","es":"¿Me puedes dar una cifra aproximada?"},{"en":"We're back to square one.","pron":"uír bak tu scuér uan","es":"Volvimos a empezar desde cero."},{"en":"Let's touch base next week.","es":"Hablemos la próxima semana."}]},{"tipo":"clave","items":["Prioridad: <b>entender</b> los idioms; úsalos tú con moderación.","<i>ballpark figure</i> = cifra aproximada · <i>back to square one</i> = desde cero.","<i>cut corners</i> = hacer a medias · <i>the bottom line</i> = lo esencial.","Elige tres o cuatro favoritos y hazlos tuyos."]}],"c-ingles-b2-m5-l3":[{"tipo":"texto","texto":"En el B1 aprendiste los phrasal verbs de todos los días (<i>set up, follow up, put off</i>). En juntas de negocios aparece otro grupo que confunde mucho, porque su significado no se adivina: <i>bring forward</i> no es «traer hacia adelante», es <b>adelantar una fecha</b>. Regla práctica: los phrasal verbs suenan <b>naturales al hablar</b>; en un informe o un contrato suele ir mejor un verbo formal (<i>postpone</i> en lugar de <i>push back</i>)."},{"tipo":"tabla","titulo":"Phrasal verbs de juntas y proyectos","voz":true,"colVoz":1,"encabezados":["Phrasal verb","Ejemplo","Español"],"filas":[["bring forward","Can we bring the meeting forward to Tuesday?","¿Podemos adelantar la junta al martes?"],["push back","The launch has been pushed back to June.","El lanzamiento se atrasó a junio."],["iron out","We still need to iron out a few details.","Todavía tenemos que resolver algunos detalles."],["draw up","Legal will draw up the contract.","Jurídico va a redactar el contrato."],["roll out","We'll roll out the new system in all branches.","Vamos a implementar el sistema nuevo en todas las sucursales."],["rule out","We can't rule out a price increase.","No podemos descartar un aumento de precio."],["come up with","She came up with a brilliant idea.","A ella se le ocurrió una idea brillante."],["take on","We're taking on ten new agents.","Vamos a contratar a diez agentes nuevos."],["back out","The investor backed out at the last minute.","El inversionista se echó para atrás en el último momento."]],"nota":"<i>push back</i> también significa «oponerse»: <i>The team pushed back on the new rules.</i> El contexto te dice cuál es."},{"tipo":"comparar","titulo":"Registro: hablar contra escribir","malTitulo":"Al hablar (natural)","mal":"<i>They pushed back the launch.</i><br><i>We need to iron out the details.</i><br><i>We're taking on new staff.</i><br><i>We can't rule it out.</i>","bienTitulo":"En un informe (formal)","bien":"<i>The launch has been <b>postponed</b>.</i><br><i>We need to <b>resolve</b> the remaining issues.</i><br><i>We are <b>hiring</b> new staff.</i><br><i>This possibility cannot be <b>excluded</b>.</i>"},{"tipo":"relacionar","rotulo":"Relaciona con su significado","voz":true,"pares":[["bring forward","adelantar"],["push back","atrasar"],["rule out","descartar"],["come up with","idear, proponer"],["roll out","implementar, lanzar"],["back out","echarse para atrás"]]},{"tipo":"practica","rotulo":"Elige el phrasal verb","preguntas":[{"p":"La junta era el viernes y ahora es el miércoles. They ___ the meeting.","ops":["pushed back","brought forward","backed out"],"correcta":1},{"p":"El cliente iba a firmar pero cambió de opinión. The client ___.","ops":["backed out","took on","drew up"],"correcta":0},{"p":"«No podemos descartar esa opción»:","ops":["We can't roll out that option.","We can't rule out that option.","We can't iron out that option."],"correcta":1},{"p":"«Se le ocurrió una solución»:","ops":["He came up with a solution.","He came out a solution.","He came with up a solution."],"correcta":0},{"p":"En un informe formal, en vez de <i>push back</i> es mejor…","ops":["postpone","bring forward","take on"],"correcta":0}]},{"tipo":"completar","rotulo":"Completa con la partícula","voz":true,"items":[{"frase":"We'll roll ___ the new app next month.","resp":["out"],"es":"Vamos a lanzar la nueva app el próximo mes."},{"frase":"Let's iron ___ the details before we sign.","resp":["out"],"es":"Resolvamos los detalles antes de firmar."},{"frase":"The lawyer is drawing ___ the agreement.","resp":["up"],"es":"El abogado está redactando el acuerdo."},{"frase":"We need to come up ___ a new marketing plan.","resp":["with"],"es":"Tenemos que idear un nuevo plan de marketing."},{"frase":"The hotel is taking ___ extra staff for the summer.","resp":["on"],"es":"El hotel está contratando personal extra para el verano."}]},{"tipo":"ordenar","rotulo":"Arma la frase","voz":true,"items":[{"frase":"Can we bring the meeting forward to Tuesday?","es":"¿Podemos adelantar la junta al martes?"},{"frase":"The launch has been pushed back to June","es":"El lanzamiento se atrasó a junio"},{"frase":"We can't rule out a price increase","es":"No podemos descartar un aumento de precio"}]},{"tipo":"clave","items":["<i>bring forward</i> = adelantar · <i>push back</i> = atrasar (o oponerse).","<i>iron out</i> = resolver detalles · <i>rule out</i> = descartar · <i>come up with</i> = idear.","<i>roll out</i> = implementar · <i>take on</i> = contratar · <i>back out</i> = echarse para atrás.","Al hablar, phrasal verbs; en informes y contratos, verbos formales."]}],"c-ingles-b2-m5-l4":[{"tipo":"texto","texto":"En inglés el orden normal es sujeto + verbo. Pero si empiezas una frase con ciertas expresiones <b>negativas o restrictivas</b> (<i>never, not only, rarely, under no circumstances, only after</i>), el orden se <b>invierte</b> como en una pregunta: <i><b>Never have I</b> seen such good results.</i> Suena formal y enfático, perfecto para discursos, presentaciones y correos importantes. También existe una inversión condicional muy usada en correos formales: <i><b>Should you</b> have any questions…</i> (= <i>If you have…</i>)."},{"tipo":"tabla","titulo":"Inversión: estructuras más útiles","voz":true,"colVoz":1,"encabezados":["Estructura","Ejemplo","Español"],"filas":[["Not only… but also","Not only did we reduce costs, but we also improved quality.","No solo redujimos costos, sino que también mejoramos la calidad."],["Never","Never have I worked with such a dedicated team.","Nunca he trabajado con un equipo tan comprometido."],["Rarely / Seldom","Rarely do we see results like these.","Pocas veces vemos resultados así."],["Under no circumstances","Under no circumstances should you share your password.","Bajo ninguna circunstancia debes compartir tu contraseña."],["Only after","Only after the audit did we find the error.","Solo después de la auditoría encontramos el error."],["Should (= if)","Should you need any further information, please contact me.","Si necesita más información, por favor contácteme."],["Had (= if + past perfect)","Had I known about the delay, I would have called you.","Si hubiera sabido del retraso, te habría llamado."]],"nota":"Para invertir usa el auxiliar como en una pregunta: <i>we reduced</i> → <i><b>did</b> we reduce</i>; <i>I have seen</i> → <i><b>have</b> I seen</i>."},{"tipo":"comparar","titulo":"El error más común","malTitulo":"Evita","mal":"<i>Not only <b>we reduced</b> costs, but…</i><br><i>Never <b>I have</b> seen this.</i><br><i>Only after the audit <b>we found</b> the error.</i><br><i><b>If should you</b> need anything…</i>","bienTitulo":"Correcto","bien":"<i>Not only <b>did we reduce</b> costs, but…</i><br><i>Never <b>have I</b> seen this.</i><br><i>Only after the audit <b>did we find</b> the error.</i><br><i><b>Should you</b> need anything…</i> (sin <i>if</i>)"},{"tipo":"practica","rotulo":"Elige la inversión correcta","preguntas":[{"p":"Not only ___ the target, but we also beat it.","ops":["we met","did we meet","we did meet"],"correcta":1},{"p":"Never ___ such a busy season in Cancún.","ops":["we have seen","have we seen","we saw"],"correcta":1},{"p":"Under no circumstances ___ leave the machine running.","ops":["should you","you should","you must to"],"correcta":0},{"p":"<i>Should you have any questions</i> significa…","ops":["Deberías tener preguntas","Si tiene alguna pregunta","Tienes que preguntar"],"correcta":1},{"p":"«Si hubiera sabido, habría venido» con inversión:","ops":["Had I known, I would have come.","If had I known, I would have come.","Would I have known, I had come."],"correcta":0}]},{"tipo":"completar","rotulo":"Completa con el auxiliar","voz":true,"items":[{"frase":"Rarely ___ we receive complaints about this product.","resp":["do"],"es":"Pocas veces recibimos quejas de este producto."},{"frase":"Only after the meeting ___ I understand the problem.","resp":["did"],"es":"Solo después de la junta entendí el problema."},{"frase":"Never ___ I seen the plant so clean.","resp":["have"],"es":"Nunca he visto la planta tan limpia."},{"frase":"___ you need any further information, please let me know.","resp":["Should"],"es":"Si necesita más información, avíseme por favor."},{"frase":"___ we known about the strike, we would have changed the route.","resp":["Had"],"es":"Si hubiéramos sabido de la huelga, habríamos cambiado la ruta."}]},{"tipo":"escuchar","rotulo":"Escucha frases con énfasis","frases":[{"en":"Not only did we meet the target, but we also beat it.","pron":"not óunli did ui mit de tárguet bat ui ólsou bit it","es":"No solo cumplimos la meta, sino que la superamos."},{"en":"Never have I worked with such a great team.","pron":"néver jav ai uérkt uíz sach a gréit tim","es":"Nunca he trabajado con un equipo tan bueno."},{"en":"Should you have any questions, please contact me.","es":"Si tiene alguna pregunta, por favor contácteme."},{"en":"Under no circumstances should you open this door.","es":"Bajo ninguna circunstancia debes abrir esta puerta."}]},{"tipo":"clave","items":["Después de <i>never, rarely, not only, only after, under no circumstances</i>: orden de pregunta.","<i>we reduced</i> → <i>did we reduce</i> · <i>I have seen</i> → <i>have I seen</i>.","En correos formales: <i>Should you need…</i> = <i>If you need…</i>","Úsala con moderación: una inversión bien puesta da fuerza; muchas suenan artificiales."]}],"c-ingles-b2-m5-l5":[{"tipo":"texto","texto":"En el B1 preparaste las preguntas básicas de una entrevista y el método STAR. Para un puesto de supervisión o gerencia, las preguntas son más incómodas: <i>What's your biggest weakness?</i>, <i>Why are you leaving?</i>, <i>Tell me about a conflict…</i>, <i>What are your salary expectations?</i> Aquí es donde todo el curso se junta: <b>hedging</b> para no sonar arrogante, <b>tiempos narrativos</b> para contar un caso, <b>condicionales</b> para reflexionar sobre tus errores y <b>collocations</b> para sonar natural."},{"tipo":"tabla","titulo":"Preguntas difíciles y cómo abordarlas","voz":true,"colVoz":1,"encabezados":["Pregunta","Respuesta modelo","Estrategia"],"filas":[["What's your biggest weakness?","I used to find it hard to delegate. Now I assign tasks weekly and check in on Fridays.","Una debilidad real + lo que haces para mejorar"],["Why are you leaving your current job?","I've learned a lot there, but I'm looking for a role with more responsibility.","Nunca hables mal de tu empresa actual"],["Tell me about a conflict with a colleague.","We disagreed about a deadline. I suggested we meet halfway, and it worked.","Caso breve con final constructivo"],["What are your salary expectations?","Based on my research, I'd be looking for something in the range of 60,000 to 70,000 pesos a month.","Un rango con base en datos"],["Do you have any questions for us?","What would success look like in this role after six months?","Siempre ten una pregunta preparada"]],"nota":"<i>Check in</i> = revisar cómo va alguien · <i>in the range of</i> = en el rango de."},{"tipo":"dialogo","titulo":"Diálogo — Entrevista para gerente regional de operaciones en una empresa de logística con sede en Dallas","lineas":[{"quien":"Ms. Brooks","en":"Tell me about a time you made a mistake at work.","es":"Cuéntame de una vez que cometiste un error en el trabajo."},{"quien":"Ricardo","en":"In 2023 we were opening a new warehouse in Querétaro. We had been working on it for months, and I was under a lot of pressure.","es":"En 2023 estábamos abriendo un almacén nuevo en Querétaro. Llevábamos meses trabajando en eso y yo estaba bajo mucha presión."},{"quien":"Ricardo","en":"I agreed to a tight deadline without checking with the IT team. If I had consulted them, we would have avoided a two-week delay.","es":"Acepté una fecha muy justa sin consultar al equipo de sistemas. Si los hubiera consultado, habríamos evitado un retraso de dos semanas."},{"quien":"Ms. Brooks","en":"And what did you learn?","es":"¿Y qué aprendiste?"},{"quien":"Ricardo","en":"Never again have I committed to a date without getting the whole team on the same page. Not only do I consult them now, but I also build in a buffer.","es":"Nunca más me he comprometido con una fecha sin poner antes de acuerdo a todo el equipo. Ahora no solo los consulto, sino que también dejo un margen."},{"quien":"Ms. Brooks","en":"That's a very honest answer. What are your salary expectations?","es":"Es una respuesta muy honesta. ¿Cuáles son tus expectativas salariales?"},{"quien":"Ricardo","en":"Based on my research, I'd be looking for something in the range of 75,000 to 85,000 pesos a month, but I'm open to discussing the full package.","es":"Con base en mi investigación, buscaría algo en el rango de 75,000 a 85,000 pesos al mes, pero estoy abierto a hablar del paquete completo."}]},{"tipo":"practica","rotulo":"Repaso de todo el curso","preguntas":[{"p":"<i>If I had consulted them, we would have avoided a delay</i> es…","ops":["Second conditional","Third conditional","Mixed conditional"],"correcta":1},{"p":"<i>We had been working on it for months</i> es…","ops":["Past perfect continuous","Pasado continuo","Present perfect"],"correcta":0},{"p":"<i>Not only do I consult them now, but I also…</i> usa…","ops":["Voz pasiva","Causativo","Inversión para énfasis"],"correcta":2},{"p":"<i>a tight deadline</i> y <i>on the same page</i> son…","ops":["Una collocation y un idiom","Dos phrasal verbs","Dos conectores"],"correcta":0},{"p":"¿Qué hace bien Ricardo al hablar de su error?","ops":["Culpa al equipo de sistemas","Lo reconoce, explica qué habría pasado y qué cambió","Dice que nunca se equivoca"],"correcta":1},{"p":"<i>I'd be looking for something in the range of…</i> es un ejemplo de…","ops":["Lenguaje diplomático / hedging","Signposting","Reported speech"],"correcta":0}]},{"tipo":"ordenar","rotulo":"Arma respuestas de entrevista","voz":true,"items":[{"frase":"I'm looking for a role with more responsibility","es":"Busco un puesto con más responsabilidad"},{"frase":"I used to find it hard to delegate","es":"Antes me costaba trabajo delegar"},{"frase":"What would success look like in this role?","es":"¿Cómo se vería el éxito en este puesto?"},{"frase":"I'm open to discussing the full package","es":"Estoy abierto a hablar del paquete completo"}]},{"tipo":"reflexion","rotulo":"Tu entrevista B2","pregunta":"Escribe tus respuestas en inglés a tres preguntas: tu mayor debilidad, un error que cometiste en el trabajo y tus expectativas salariales. Incluye en total al menos: un third o mixed conditional, un past perfect continuous, una frase suavizada (hedging), una collocation y una inversión. Luego grábate respondiendo en voz alta sin leer.","ayuda":"I used to… Now I… / We had been… for… / If I had…, I would have… / Not only did I…, but I also… / I'd be looking for something in the range of…"},{"tipo":"pronunciar","rotulo":"Responde con seguridad","frases":[{"en":"I used to find it hard to delegate.","pron":"ai iúst tu fáind it jard tu délegueit","es":"Antes me costaba trabajo delegar."},{"en":"If I had consulted them, we would have avoided the delay.","es":"Si los hubiera consultado, habríamos evitado el retraso."},{"en":"I'd be looking for something in the range of 80,000 pesos.","pron":"aid bi lúking for sámzing in de réinch ov éiti záusand péisos","es":"Buscaría algo en el rango de 80,000 pesos."},{"en":"What would success look like in this role?","es":"¿Cómo se vería el éxito en este puesto?"}]},{"tipo":"clave","items":["Debilidad = algo real + lo que haces para mejorar. Nunca hables mal de tu empleo actual.","Cuenta tus errores con tiempos narrativos y un third conditional: muestra que aprendiste.","Salario: un rango con base en datos, con tono suavizado (<i>I'd be looking for…</i>).","Terminaste el curso: repasa los módulos que te costaron más y presenta la evaluación final (80%)."]}]},"q":{"c-ingles-b2-m1":[{"p":"«Si hubiera sabido, te habría llamado» se dice…","ops":["If I would have known, I would have called you.","If I knew, I would call you.","If I had known, I would have called you.","If I had known, I would call you yesterday."],"correcta":2},{"p":"Completa: <i>If I had taken that job, I ___ in Toronto now.</i>","ops":["would be living","would have lived","will live","had lived"],"correcta":0},{"p":"Completa: <i>If she ___ more organized, she wouldn't have lost the file.</i>","ops":["would be","were","has been","will be"],"correcta":1},{"p":"«Ojalá te vaya bien en la entrevista» (es posible):","ops":["I wish you do well in the interview.","I wish you did well in the interview.","I hope you would do well in the interview.","I hope you do well in the interview."],"correcta":3},{"p":"«Ojalá no hubiera dicho eso» se dice…","ops":["I wish I hadn't said that.","I hope I didn't say that.","I wish I wouldn't say that.","I wish I don't say that."],"correcta":0},{"p":"¿Cuál es correcta?","ops":["I'd rather to stay here.","I'd rather you didn't smoke inside.","You had better to go.","It's time we update the prices on the website."],"correcta":1},{"p":"Las luces están apagadas y nadie contesta. <i>They ___ gone home.</i>","ops":["should have","can't have","must have","would have"],"correcta":2},{"p":"«Debimos haber confirmado ayer» se dice…","ops":["We must have confirmed it yesterday.","We should confirm yesterday.","We should of confirmed yesterday.","We should have confirmed yesterday."],"correcta":3}],"c-ingles-b2-m2":[{"p":"¿Cuál es un buen ejemplo de hedging?","ops":["The report is wrong.","The report seems to have a few errors.","The report is terrible and completely wrong.","Wrong report."],"correcta":1},{"p":"<i>It might be worth checking with legal</i> significa…","ops":["Legal cuesta mucho","Hay que pagarle a jurídico antes de revisar","Quizá valga la pena consultarlo con jurídico","Jurídico ya lo revisó"],"correcta":2},{"p":"La forma más diplomática de pedir algo es…","ops":["I want a new date.","Give me a new date.","You must change the date of the meeting now.","I was wondering if we could change the date."],"correcta":3},{"p":"<i>Pretend</i> en inglés significa…","ops":["Fingir","Pretender, tener la intención","Preferir","Prevenir"],"correcta":0},{"p":"Para persuadir, una pregunta retórica útil es…","ops":["Why don't you understand?","Wouldn't it make sense to try it first?","Are you crazy?","Do you want to lose money and customers?"],"correcta":1},{"p":"Te interrumpen a media idea. Dices…","ops":["Be quiet.","Wait, wait, wait! Let me talk!","Sorry, can I just finish my point?","You are rude."],"correcta":2},{"p":"Completa: <i>We can lower the price provided that you ___ for two years.</i>","ops":["sign","will sign","would sign","signed"],"correcta":0},{"p":"<i>That's a deal-breaker for us</i> significa…","ops":["Ya cerramos el trato","Eso rompe el trato: no lo podemos aceptar","Es una ganga","Necesitamos un descanso antes de seguir negociando"],"correcta":1}],"c-ingles-b2-m3":[{"p":"¿Cuál es un buen «letrero» para cambiar de tema?","ops":["Now I pass to the part of the costs.","That brings me to the costs.","In resume, the costs.","The costs, now."],"correcta":1},{"p":"«Déjame explicarte el proceso» se dice…","ops":["Let me explain you the process.","Let me explain the process to you.","Let me explain to the process you.","Let me explain you about the process."],"correcta":1},{"p":"Completa: <i>When I joined, the company ___ money for two years.</i>","ops":["had been losing","has been losing","was lost","is losing"],"correcta":0},{"p":"Completa: <i>By the time we arrived, the meeting ___.</i>","ops":["has finished","finishes","had finished","was finish"],"correcta":2},{"p":"<i>Having said that</i> sirve para…","ops":["Concluir","Añadir una idea igual a la anterior","Matizar o contrastar lo que acabas de decir","Pedir la palabra"],"correcta":2},{"p":"«Al final elegimos al proveedor local» se dice…","ops":["At the end, we chose the local supplier.","In the end, we chose the local supplier.","Resuming, we chose the local supplier.","On the end, we chose the local supplier."],"correcta":1},{"p":"Las ventas pasaron de 200 a 250. <i>Sales rose ___ 25%.</i>","ops":["in","of","by","on"],"correcta":2},{"p":"Te preguntan un dato que no tienes. Lo mejor es…","ops":["Inventar una cifra aproximada","Decir que la pregunta no importa para la decisión","Admitirlo y prometer enviarlo: I'll get back to you by Friday.","Cambiar de tema"],"correcta":2}],"c-ingles-b2-m4":[{"p":"¿Cuál es correcta?","ops":["Despite of the rain, we traveled.","Although the rain, we traveled.","Despite the rain, we traveled.","In spite the rain, we traveled."],"correcta":2},{"p":"Completa: <i>Our team works in the morning, ___ theirs works at night.</i>","ops":["whereas","despite","therefore","due to"],"correcta":0},{"p":"«Están revisando el contrato» (en este momento):","ops":["The contract is reviewed.","The contract is being reviewed.","The contract has being reviewed.","The contract is reviewing."],"correcta":1},{"p":"«Se espera que la planta abra en marzo»:","ops":["The plant expects to open in March.","It expects that the plant opens in March.","The plant is expected to open in March.","The plant is expecting open in March."],"correcta":2},{"p":"Fuiste al peluquero. Dices…","ops":["I cut my hair yesterday.","I had my hair cut yesterday.","I had cut my hair yesterday.","I have my hair cutting yesterday."],"correcta":1},{"p":"Completa: <i>Can you get the supplier ___ the price?</i>","ops":["lower","lowered","to lower","lowering"],"correcta":2},{"p":"¿Qué va primero en un informe en inglés?","ops":["El executive summary con la recomendación","Todo el contexto histórico del proyecto desde el inicio","Los agradecimientos","Los anexos"],"correcta":0},{"p":"La forma más profesional de disculparte es…","ops":["Sorry for the inconveniences caused!!","We sincerely apologize for the delay.","Sorry, it was not our fault.","We apologize for the late."],"correcta":1}],"c-ingles-b2-m5":[{"p":"¿Cuál es la collocation natural?","ops":["make a question","do a mistake","meet a deadline","win experience"],"correcta":2},{"p":"«Había mucho tráfico» se dice…","ops":["There was strong traffic.","There was heavy traffic.","There was big traffic.","There was a lot traffic."],"correcta":1},{"p":"<i>Can you give me a ballpark figure?</i> significa…","ops":["¿Me das una cifra aproximada?","¿Me das la cifra exacta al centavo?","¿Vamos al estadio?","¿Me das tu opinión?"],"correcta":0},{"p":"«Volvimos a empezar desde cero»:","ops":["We cut corners.","We called it a day.","We're on the same page again.","We're back to square one."],"correcta":3},{"p":"La junta se movió del viernes al miércoles. <i>They ___ the meeting.</i>","ops":["pushed back","brought forward","ruled out","backed out"],"correcta":1},{"p":"«No podemos descartar esa opción»:","ops":["We can't rule out that option.","We can't roll out that option.","We can't draw up that option.","We can't take on that option."],"correcta":0},{"p":"¿Cuál es correcta?","ops":["Not only we reduced costs, but we also improved quality.","Not only did we reduce costs, but we also improved quality.","Not only reduced we costs, but we also improved quality.","Not only we did reduce costs, but we also improved quality."],"correcta":1},{"p":"En una entrevista, al hablar de tu mayor debilidad lo mejor es…","ops":["Decir que no tienes debilidades porque eres perfeccionista","Hablar mal de tu jefe actual","Mencionar algo real y lo que haces para mejorar","Cambiar de tema"],"correcta":2}]}});
